\subsection{Sampling-dependent smoothness constants}
We now define two smoothness constants that depend on the weights $\{w_i\}_{i=1}^n$ of a sampling $\samplefunc$ and on the functions $f_i.$ 
\begin{definition}
  \label{def:weighted_local_lipschitz_constant}
Given a sampling $\samplefunc \in \mathbb{S}(A, B, \{w_i\}_{i=1}^n)$, let  $L_{+,w}$ be a constant for which 
  $$\squeeze \frac{1}{n} \sum \limits_{i=1}^n \frac{1}{n w_i}\norm{\nabla f_i(x) - \nabla f_i(y)}^2 \leq L_{+,w}^2 \norm{x - y}^2, \quad \forall x, y \in \R^d.$$
For $(w_1, \dots, w_n) = (\nicefrac{1}{n}, \dots, \nicefrac{1}{n}),$ we define $L_{+} \eqdef L_{+,w}.$
\end{definition}
\begin{definition}
  \label{def:weighted_hessian_varaince}
Given a sampling $\samplefunc \in \mathbb{S}(A, B, \{w_i\}_{i=1}^n)$, let $L_{\pm,w}$ be a constant for which
  $$\squeeze \frac{1}{n} \sum \limits_{i=1}^n \frac{1}{n w_i}\norm{\nabla f_i(x) - \nabla f_i(y)}^2 - \norm{\nabla f(x) - \nabla f(y)}^2 \leq L_{\pm,w}^2 \norm{x - y}^2, \qquad \forall x, y \in \R^d.$$
For $(w_1, \dots, w_n) = (\nicefrac{1}{n}, \dots, \nicefrac{1}{n}),$ we define $L_{\pm} \eqdef L_{\pm,w}.$
\end{definition}
One can interpret Definition~\ref{def:weighted_local_lipschitz_constant} as \textit{weighted} mean-squared smoothness property \citep{arjevani2019lower}, and Definition~\ref{def:weighted_hessian_varaince} as \textit{weighted} Hessian variance  \citep{szlendak2021permutation} that captures the similarity between the functions $f_i$.
The constants $L_{+,w}$ and $L_{\pm,w}$ help us better to understand the structure of the optimization problem \eqref{eq:main_problem} {\em in connection} with a particular choice of a sampling scheme. The next result states that $L_{+,w}^2$ and $L_{\pm,w}^2$ are finite provided the functions $f_i$ are $L_i$--smooth for all $i \in [n].$
\begin{theorem}
  \label{theorem:l_estimation}
If Assumption~\ref{ass:local_lipschitz_constant} holds, then $L_{+,w}^2 = L_{\pm,w}^2 = \frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i} L_i^2$ satisfy Def.~\ref{def:weighted_local_lipschitz_constant} and \ref{def:weighted_hessian_varaince}.
\end{theorem}
 Indeed, from Assumption~\ref{ass:local_lipschitz_constant} and the inequality $\norm{\nabla f(x) - \nabla f(y)}^2 \geq 0$  we get
  $$\squeeze \frac{1}{n} \sum \limits_{i=1}^n \frac{1}{n w_i}\norm{\nabla f_i(x) - \nabla f_i(y)}^2 - \norm{\nabla f(x) - \nabla f(y)}^2 \leq \left(\frac{1}{n} \sum \limits_{i=1}^n \frac{1}{n w_i}L_i^2\right)\norm{x - y}^2,$$
  thus we can take $L_{\pm,w}^2 = \frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i}L_i^2.$ The proof for $L_{+,w}^2$ is the same.

From the proof, one can see that we ignore $\norm{\nabla f(x) - \nabla f(y)}^2$ when estimating $L_{\pm,w}^2.$ However, by doing that, the obtained result is not tight.


\section{A General and Refined Theoretical Analysis of  \algname{\large PAGE}}
\label{sec:theorems}
In the Algorithm~\ref{alg:page}, we provide the description of the \algname{PAGE} method. The choice of \algname{PAGE} as the base method is driven by the simplicity of the proof in the original paper. However, we believe that other methods, including \algname{SPIDER} and \algname{SARAH}, can also admit samplings from Assumption~\ref{ass:sampling}.

\begin{algorithm}[!t]
  \caption{\algname{PAGE}}
  \label{alg:page}
  \begin{algorithmic}[1]
  \STATE \textbf{Input:} initial point $x^0\in \R^d$, stepsize $\gamma>0$, probability ${p} \in (0, 1]$
  \STATE $g^0 = \nabla f(x^0)$
  \FOR{$t =0,1,\dots$}
  \STATE $x^{t+1} = x^t - \gamma g^t$
  \STATE Generate a random sampling function $\samplefunc^t$
  \STATE $
      g^{t+1}=
      \begin{cases}
           \nabla f(x^{t+1}) & \text{with probability}\ p \\
          g^t + \samplefunc^t\left(\{\nabla f_i(x^{t+1}) - \nabla f_i(x^{t})\}_{i=1}^n\right) & \text{with probability}\ 1 - p \\
      \end{cases}
      $
  \ENDFOR
  \end{algorithmic}
\end{algorithm}

In this section, we provide theoretical results for Algorithm~\ref{alg:page}. Let us define $\Delta_0 \eqdef f(x^0) - f^*.$

\begin{restatable}{theorem}{THEOREMCONVERGENCEPAGE}
	\label{theorem:pageab}
	Suppose that Assumptions~\ref{ass:lower_bound}, \ref{ass:lipschitz_constant}, \ref{ass:local_lipschitz_constant} hold and the samplings $\samplefunc^t \in \mathbb{S}(A, B, \{w_i\}_{i=1}^n)$. Then Algorithm~\ref{alg:page} \algname{(PAGE)} has the convergence rate
	$\Exp{\norm{\nabla f(\widehat{x}^T)}^2} \leq \frac{2\Delta_0}{\gamma T},$
	where
	$\gamma \leq \left(L_- + \sqrt{\frac{1 - p}{p} \left(\left(A - B\right)L_{+,w}^2 + B L_{\pm,w}^2\right)}\right)^{-1}.$
\end{restatable}

To reach an $\varepsilon$-stationary point, it is enough to do 
\begin{align}
  \label{eq:rate}
 \squeeze  T \eqdef \frac{2\Delta_0}{\varepsilon}\left(L_- + \sqrt{\frac{1 - p}{p} \left(\left(A - B\right)L_{+,w}^2 + B L_{\pm,w}^2\right)}\right)
\end{align}
 iterations of Algorithm~\ref{alg:page}. To deduce the gradient complexity, we provide the following corollary.

\begin{restatable}{corollary}{COROLLARYCONVERGENCEPAGE}
	\label{corollary:pageab}
	Suppose that the assumptions of Thm~\ref{theorem:pageab} hold. Let us take $p = \frac{|\samplefunc|}{|\samplefunc| + n}.$ Then the complexity (the expected number of gradient calculations $\nabla f_i$) of Algorithm~\ref{alg:page} equals
  \begin{eqnarray*}
\squeeze 		N \eqdef \Theta\left(n + |\samplefunc| T\right) = \Theta\left(n + \frac{\Delta_0}{\varepsilon} |\samplefunc| \left(L_- + \sqrt{\frac{n}{|\samplefunc|} \left(\left(A - B\right)L_{+,w}^2 + B L_{\pm,w}^2\right)}\right)\right).
	\end{eqnarray*}
\end{restatable}
\begin{proof}
  At each iteration, the expected \# gradient calculations equals $p n + (1 - p) |\samplefunc| \leq 2 |\samplefunc|.$ Thus the total expected number of gradient calculations equals $n + 2 |\samplefunc| T$ to get an $\varepsilon$-stationary point.
\end{proof}

The original result from \citep{PAGE} states that the complexity of \algname{PAGE} with batch size $\tau$ is
\begin{eqnarray}
  \label{eq:compl_page}
\squeeze   N_{\textnormal{orig}} \eqdef \Theta\left(n + \frac{\Delta_0}{\varepsilon} \tau \left(L_- + \frac{\sqrt{n}}{\tau} L_{+}\right)\right) \geq \Theta\left(n + \frac{\Delta_0\sqrt{n} L_{+}}{\varepsilon}\right),
\end{eqnarray}


\subsection{\samplingname{Uniform With Replacement} sampling}
Let us do a sanity check and substitute the parameters of the sampling that the original paper uses. We take the \samplingname{Uniform With Replacement} sampling (see Sec~\ref{subsec:3}) with batch size $\tau$ (note that $\tau \geq |\samplefunc|$), $A = B = \nicefrac{1}{\tau}$ and $w_i = \nicefrac{1}{n}$ for all $i \in [n]$ (see Table~\ref{tbl:AB}) and get the complexity $N_{\textnormal{uniform}} = \Theta\left(n + \frac{\Delta_0}{\varepsilon} \tau \left(L_- + \frac{\sqrt{n}}{\tau} L_{\pm}\right)\right).$ Next, let us fix $\tau \leq \max\left\{\frac{\sqrt{n} L_{\pm}}{L_{-}},1\right\},$ and, finally, obtain that $N_{\textnormal{uniform}} = \Theta\left(n + \frac{\Delta_0\max\{\sqrt{n} L_{\pm}, L_{-}\}}{\varepsilon}\right).$ Let us compare it with \eqref{eq:compl_page}. With the \textbf{same sampling}, our analysis provides better complexity; indeed, note that $\max\{\sqrt{n} L_{\pm}, L_{-}\} \leq \sqrt{n} L_{+}$ (see Lemma~2 in \cite{szlendak2021permutation}). Moreover, \cite{szlendak2021permutation} provides examples of the optimization problems when $L_{\pm}$ is small and $L_{+}$ is large, so the difference can be arbitrary large.

\subsection{\samplingname{Nice} sampling}
Next, we consider the \samplingname{Nice} sampling (see Sec~\ref{subsec:0}) and get that the complexity $N_{\textnormal{nice}} = \Theta\left(n + \frac{\Delta_0}{\varepsilon} \tau \left(L_- + \frac{1}{\tau}\sqrt{\frac{n (n-\tau)}{(n-1)}}L_{\pm}\right)\right).$ 
Unlike the \samplingname{Uniform With Replacement} sampling, the \samplingname{Nice} sampling recovers the complexity of \algname{GD} for $\tau = n.$

\subsection{\samplingname{Importance} sampling}
Let us consider the \samplingname{Importance} sampling (see Sec~\ref{subsec:3}) that justifies the introduction of the weights $w_i.$ We can get the complexity $N_{\textnormal{importance}} = \Theta\left(n + \frac{\Delta_0}{\varepsilon} \tau \left(L_- + \frac{\sqrt{n}}{\tau} L_{\pm,w}\right)\right) \leq \Theta\left(n + \frac{\Delta_0\max\{\sqrt{n} L_{\pm,w}, L_{-}\}}{\varepsilon}\right)$ for $\tau \leq \max\left\{\frac{\sqrt{n} L_{\pm,w}}{L_{-}},1\right\}.$ Now, we take $q_i = w_i = \frac{L_i}{\sum_{i=1} L_i}$ and use the results from Sec~\ref{sec:optimal_weights} to obtain $N_{\textnormal{importance}} = \Theta\left(n + \frac{\Delta_0\sqrt{n} \left(\frac{1}{n} \sum_{i=1}^n L_i\right)}{\varepsilon}\right) \leq N_{\textnormal{orig}}.$ In Example~\ref{ex:lipt_sum}, we consider the optimization task where $\frac{1}{n} \sum_{i=1}^n L_i$ is $\sqrt{n}$ times smaller than $L_{+}.$ Thus the complexity $N_{\textnormal{importance}}$ can be at least $\sqrt{n}$ times smaller that the complexity $N_{\textnormal{orig}}.$

\subsection{The power of $B > 0$}
In all previous examples, the constant $A = B > 0.$ If $A = B,$ then the complexity $N  = \Theta\left(n + \frac{\Delta_0}{\varepsilon} |\samplefunc| \left(L_- + \sqrt{\frac{n}{|\samplefunc|} B L_{\pm,w}^2}\right)\right),$ thus the complexity $N$ does not depend on $L_{+,w}^2,$ which greater of equal to $L_{\pm,w}^2.$ This is the first analysis of optimal SGD, which uses $B > 0.$

\subsection{Analysis under P\L\,Condition}

The previous results can be extended to the optimization problems that satisfy the Polyak-\L ojasiewicz condition. Under this assumption, Algorithm~\ref{alg:page} enjoys a linear convergence rate.

\begin{assumption}
  \label{ass:pl}
  There exists $\mu > 0$ such that the function $f$ satisfy (Polyak-\L ojasiewicz) P\L-condition:
  \begin{align*}
      \norm{\nabla f(x)}^2 \geq 2\mu(f(x) - f^*) \quad \forall x \in \R,
  \end{align*}
  where $f^* = \inf_{x \in \R^d} f(x) > -\infty.$
\end{assumption}

Using Assumption~\ref{ass:pl}, we can improve the convergence rate of \algname{PAGE}.

\begin{restatable}{theorem}{THEOREMCONVERGENCEPAGEPL}
	\label{theorem:pageabpl}
	Suppose that Assumptions~\ref{ass:lower_bound}, \ref{ass:lipschitz_constant}, \ref{ass:local_lipschitz_constant}, \ref{ass:pl} and the samplings $\samplefunc^t \in \mathbb{S}(A, B, \{w_i\}_{i=1}^n)$. Then Algorithm~\ref{alg:page} \algname{(PAGE)} has the convergence rate
	$\Exp{f(x^T)} - f^* \leq (1 - \gamma \mu)^T \Delta_0,$
	where
	$\gamma \leq \min\left\{\left(L_- + \sqrt{\frac{2(1 - p)}{p} \left(\left(A - B\right)L_{+,w}^2 + B L_{\pm,w}^2\right)}\right)^{-1}, \frac{p}{2\mu}\right\}.$
\end{restatable}


\section{Composition of Samplings: Application to Federated Learning}
\label{sec:sampling_in_sampling}
In Sec~\ref{sec:theorems}, we analyze the \algname{PAGE} method with samplings that satisfy Assumption~\ref{ass:sampling}. Now, let us assume that the functions $f_i$ have the finite-sum form, i.e., $f_i(x) \eqdef \frac{1}{m_i} \sum_{j=1}^{m_i} f_{ij}(x),$ thus we an optimization problem
\begin{align}
  \label{eq:main_problem:group} 
\squeeze   \min \limits \limits_{x \in \R^d}\left\{f(x) \eqdef \frac{1}{n} \sum \limits_{i=1}^n \frac{1}{m_i} \sum \limits_{j=1}^{m_i} f_{ij}(x)\right\},
\end{align}
Another way to get the problem is to assume that we split the functions $f_i$ into groups of sizes $m_i.$ All in all, let us consider \eqref{eq:main_problem:group} instead of \eqref{eq:main_problem}.

The problem \eqref{eq:main_problem:group} occurs in many applications, including distributed optimization and federated learning \citep{konevcny2016federated, mcmahan2017communication}. In federated learning, many devices and machines (nodes) store local datasets that they do not share with other nodes. The local datasets are represented by functions $f_i,$ and all nodes solve the common optimization problem \eqref{eq:main_problem:group}. Due to privacy reasons and communication bottlenecks \citep{kairouz2021advances}, 
it is infeasible to store and compute the functions $f_i$ locally in one machine.

In general, when we solve \eqref{eq:main_problem} in one machine, we have the freedom of choosing a sampling $\samplefunc$ for the functions $f_i,$ which we have shown in Sec~\ref{sec:theorems}. However, in federated learning, a sampling of nodes or the functions $f_i$ is dictated by hardware limits or network quality \citep{kairouz2021advances}. Still, each $i$\textsuperscript{th} node can choose sampling $\samplefunc_i$ to sample the functions $f_{ij}.$ As a result, we have a composition of the sampling $\samplefunc$ and the samplings $\samplefunc_i$ (see Algorithm~\ref{alg:page:composition}).

\begin{assumption}
  \label{ass:local_local_lipschitz_constant}
  For all $j \in [m_i], i \in [n],$ there exists a Lipschitz constant $L_{ij}$ such that $\norm{\nabla f_{ij}(x) - \nabla f_{ij}(y)} \leq L_{ij} \norm{x - y}$ for all $x, y \in \R^d.$
\end{assumption}

We now introduce the counterpart of Definitions~\ref{def:weighted_local_lipschitz_constant} and \ref{def:weighted_hessian_varaince}.
\begin{definition}
  \label{def:weighted_local_lipschitz_constant:local}
  For all $i \in [n]$ and any sampling $\samplefunc_i \in \mathbb{S}(A_i, B_i, \{w_{ij}\}_{j=1}^{m_i})$,  define  constant $L_{i,+,w_i}$ such that 
  $$\squeeze \frac{1}{m_i} \sum \limits_{j=1}^{m_i} \frac{1}{m_i w_{ij}}\norm{\nabla f_{ij}(x) - \nabla f_{ij}(y)}^2 \leq L_{i,+,w_i}^2 \norm{x - y}^2 \quad \forall x, y \in \R^d.$$
\end{definition}
\begin{definition}
  \label{def:weighted_hessian_varaince:local}
  For all $i \in [n]$ and any sampling $\samplefunc_i \in \mathbb{S}(A_i, B_i, \{w_{ij}\}_{j=1}^{m_i})$,  define constant $L_{i,\pm,w_i}$ such that 
  $$\squeeze \frac{1}{m_i} \sum \limits_{j=1}^{m_i} \frac{1}{m_i w_{ij}}\norm{\nabla f_{ij}(x) - \nabla f_{ij}(y)}^2 - \norm{\nabla f_i(x) - \nabla f_i(y)}^2 \leq L_{i,\pm,w_i}^2 \norm{x - y}^2 \quad \forall x, y \in \R^d.$$
\end{definition}

\begin{algorithm}[!t]
  \caption{\algname{PAGE} with  composition of samplings}
  \label{alg:page:composition}
  \begin{algorithmic}[1] 
  \STATE \textbf{Input:} initial point $x^0\in \R^d$, stepsize $\gamma>0$, probability ${p} \in (0, 1]$, $g^0 = \nabla f(x^0)$
  \FOR{$t =0,1,\dots$}
  \STATE $x^{t+1} = x^t - \gamma g^t$
  \STATE $
  c^{t+1}=
  \begin{cases}
       1 & \text{with probability}\ p \\
       0 & \text{with probability}\ 1 - p \\
  \end{cases}
  $
  \IF{$c^{t+1} = 1$}
  \STATE $g^{t+1} = \nabla f(x^{t+1})$ 
  \ELSE
  \STATE Generate samplings $\samplefunc^t_i$ for all $i \in [n]$
  \STATE $h^{t+1}_i = \samplefunc^t_i\left(\{\nabla f_{ij}(x^{t+1}) - \nabla f_{ij}(x^{t})\}_{j=1}^{m_i}\right)$ for all $i \in [n]$
  \STATE Generate a sampling $\samplefunc^t$ and  set $g^{t+1} = g^t + \samplefunc^t\left(\{h^{t+1}_i\}_{i=1}^n\right)$
  \ENDIF
  \ENDFOR
  \end{algorithmic}
\end{algorithm}

Let us provide the counterpart of Thm~\ref{theorem:pageab} for Algorithm~\ref{alg:page:composition}.

\begin{restatable}{theorem}{THEOREMCONVERGENCEPAGECOMPOSITION}
	\label{theorem:pageab:composition}
	Suppose that Assumptions~\ref{ass:lower_bound}, \ref{ass:lipschitz_constant}, \ref{ass:local_lipschitz_constant}, \ref{ass:local_local_lipschitz_constant} hold and the samplings $\samplefunc^t \in \mathbb{S}(A, B, \{w_{i}\}_{i=1}^{n})$ and the samplings $\samplefunc^t_i \in \mathbb{S}(A_i, B_i, \{w_{ij}\}_{j=1}^{m_i})$ for all $i \in [n].$ Moreover, $B \leq 1.$ Then Algorithm~\ref{alg:page:composition} has the convergence rate
	$\Exp{\norm{\nabla f(\widehat{x}^T)}^2} \leq \frac{2\Delta_0}{\gamma T},$
	where
  \resizebox{.99\linewidth}{!}{
    \begin{minipage}{\linewidth}
    \begin{align*}
    \gamma \leq \left(L_- + \sqrt{\frac{1 - p}{p} \left(\frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left((A_i - B_i) L_{i,+,w_i}^2 + B_i L_{i,\pm,w_i}^2\right) + (A - B)L_{+,w}^2 + B L_{\pm,w}^2\right)}\right)^{-1}.
    \end{align*}
    \end{minipage}
  }
\end{restatable}

The obtained theorem provides a general framework that helps analyze the convergence rates of the composition of samplings that satisfy Assumption~\ref{ass:sampling}. We discuss the obtained result in different contexts.

\subsection{Federated Learning}
For simplicity, let us assume that the samplings $\samplefunc^t$ and $\samplefunc_i^t$ are \textit{Uniform With Replacement} samplings with batch sizes $\tau$ and $\tau_i$ for all $i \in n$, accordingly, then to get $\varepsilon$-stationary point, it is enough to do
$
  T \eqdef \Theta\left(\frac{\Delta_0}{\varepsilon} \left(L_- + \sqrt{\frac{1 - p}{p \tau} \left(\frac{1}{n}\sum_{i = 1}^n \frac{1}{\tau_i} L_{i,\pm}^2 + L_{\pm}^2\right)}\right)\right)
$
iterations. Note that 
$
  T \geq \Theta\left(\frac{\Delta_0}{\varepsilon} \left(L_- + \sqrt{\frac{1 - p}{p \tau} L_{\pm}^2}\right)\right)
$
for all $\tau_i \geq 1$ for all $i \in [n].$ It means that after some point, there is no benefit in increasing batch sizes $\tau_i.$ In order to balance $\frac{1}{n}\sum_{i = 1}^n \frac{1}{\tau_i} L_{i,\pm}^2$ and $L_{\pm}^2,$ one can take $\tau_i = \Theta\left(\nicefrac{L_{i,\pm}^2}{L_{\pm}^2}\right).$ The constant $L_{i,\pm}^2$ captures the \textit{intra-variance} inside $i$\textsuperscript{th} node, while $L_{\pm}^2$ captures the \textit{inter-variance} between nodes. If the \textit{intra-variance} is small with respect to the \textit{inter-variance}, then our theory suggests taking small batch sizes and vice versa. 

\subsection{\samplingname{Stratified} sampling}
Let us provide another example that is closely related to \citep{zhao2014accelerating}. Let us consider \eqref{eq:main_problem} and use a variation of the \textit{Stratified} sampling \citep{zhao2014accelerating}: we split the functions $f_i$ into $g = \nicefrac{n}{m}$ groups, where $m$ is the number of functions in each group. Thus we get the problem \eqref{eq:main_problem:group} with $f(x) = \frac{1}{g} \sum_{i=1}^g \frac{1}{m} \sum_{j=1}^{m} f_{ij}(x).$
Let us assume that we always sample \textit{all} groups, thus $A = B = 0,$ and the sampling $\samplefunc_i^t$ are \textit{Nice} samplings with batch sizes $\tau_1$ for all $i \in [n].$ Applying Thm~\ref{theorem:pageab:composition}, we get the convergence rate
$
  T_{\textnormal{group}} \eqdef \Theta\left(\frac{\Delta_0}{\varepsilon} \left(L_- + \sqrt{\frac{1 - p}{p g \tau_1}\left(\frac{1}{g}\sum_{i = 1}^g L_{i,\pm}^2\right)}\right)\right).
$
At each iteration, the algorithm calculates $g \tau_1$ gradients, thus we should take $p = \frac{g \tau_1}{g \tau_1 + n}$ to get the complexity
$
  N_{\textnormal{group}} \eqdef \Theta\left(n + g \tau_1 T\right) = \Theta\left(n + \frac{\Delta_0}{\varepsilon} \left(g \tau_1 L_- + \sqrt{n}\sqrt{\frac{1}{g}\sum_{i = 1}^g L_{i,\pm}^2}\right)\right).
$
Let us take $\tau_1 \leq \max\left\{\frac{\sqrt{n} \sqrt{\frac{1}{g}\sum_{i = 1}^g L_{i,\pm}^2}}{g L_{-}}, 1\right\}$ to obtain the complexity $N_{\textnormal{group}} = \Theta\left(n + \frac{\Delta_0 \max\left\{\sqrt{n} \sqrt{\frac{1}{g}\sum_{i = 1}^g L_{i,\pm}^2}, g L_{-}\right\}}{\varepsilon}\right).$ Comparing the complexity $N_{\textnormal{group}}$ with the complexity $N_{\textnormal{uniform}}$ from Sec~\ref{sec:theorems}, one can see that if split the functions $f_i$ in a ``right way'', such that $L_{i,\pm}$ is small for $i \in [n]$ (see Example~\ref{ex:groups}), then we can get at least $\nicefrac{\sqrt{n}}{\sqrt{g}}$ times improvement with the \textit{Stratified} sampling.

\section{Experiments}
\label{sec:experiments}
We now provide experiments\footnote{Our code: \url{https://github.com/mysteryresearcher/sampling-in-optimal-sgd}} with synthetic quadratic optimization tasks, where the functions $f_i$, in general, are nonconvex quadratic functions. Note that our goal here is to check whether the dependencies that our theory predicts are correct for the problem \eqref{eq:main_problem}. The procedures that generate synthetic quadratic optimization tasks give us control over the choice of smoothness constants. All parameters of Algorithm~\ref{alg:page} are chosen as suggested in Thm~\ref{theorem:pageab} and Cor~\ref{corollary:pageab}. In the plots, we represent the relation between the norm of gradients and the number of gradient calculations $\nabla f_i$.

\subsection{Quadratic optimization tasks with various Hessian Variances $L_{\pm}$}

\label{sec:experiment:quadratic_l_pm}

Using Algorithm~\ref{algorithm:matrix_generation} (see Appendix), we generated various quadratic optimization tasks with different smoothness constants $L_{\pm} \in [0, 1.0]$ and fixed $L_{-} \approx 1.0$ (see Fig.~\ref{fig:page_ab_arxiv_2022_nodes_1000_nl_0_01_05_1_10_dim_10_wc_with_compl_more_info}). We choose $d = 10,$  $n = 1000,$  regularization $\lambda = 0.001,$ and the noise scale $s \in \{0, 0.1, 0.5, 1\}.$ According to Sec~\ref{sec:theorems} and Table~\ref{tbl:compl}, the gradient complexity of original \algname{PAGE} method (``Vanilla PAGE'' in Fig.~\ref{fig:page_ab_arxiv_2022_nodes_1000_nl_0_01_05_1_10_dim_10_wc_with_compl_more_info}) is proportional to $L_{+}.$ While the gradient complexity of the new analysis with the \samplingname{Uniform With Replacement} 
sampling (``Uniform With Replacement'' in Fig.~\ref{fig:page_ab_arxiv_2022_nodes_1000_nl_0_01_05_1_10_dim_10_wc_with_compl_more_info}) is proportional to $L_{\pm},$ which is always less or equal $L_{+}.$ In Fig.~\ref{fig:page_ab_arxiv_2022_nodes_1000_nl_0_01_05_1_10_dim_10_wc_with_compl_more_info}, one can see that the smaller $L_{\pm}$ with respect to $L_{+},$ the better the performance of ``Uniform With Replacement.''  Moreover, we provide experiments with the \samplingname{Importance} sampling (``Importance'' in Fig.~\ref{fig:page_ab_arxiv_2022_nodes_1000_nl_0_01_05_1_10_dim_10_wc_with_compl_more_info}) with $q_i = \frac{L_{i}}{\sum_{i=1}^n L_i}$ for all $i \in [n].$ This sampling has the best performance in all regimes. 

