\section{Examples of Optimization Problems}

\begin{example}
  \normalfont
  \label{ex:lipt}
  For simplicity, let us assume that $n$ is even. Let us consider the optimization problem \eqref{eq:main_problem} with $f_i(x) = \frac{a}{2} x^2 + \frac{b}{2} x^2$ for $i \in \{1, \cdots, n / 2\}$ and $f_i(x) = -\frac{a}{2} x^2 + \frac{b}{2} x^2$ for $i \in \{n / 2 + 1, \cdots, n\},$ where $x \in \R$ and $b \geq 0.$ Then $f(x) = \frac{b}{2} x^2$ and $$L_{-}^2 = \sup_{x \neq y} \frac{\norm{\nabla f(x) - \nabla f(y)}^2}{\norm{x - y}^2} = b^2.$$ Moreover, 
  $$L_{+}^2 = \sup_{x \neq y} \frac{\frac{1}{n}\sum_{i=1}^n\norm{\nabla f_i(x) - \nabla f_i(y)}^2}{\norm{x - y}^2} = \frac{1}{2}\left((a + b)^2 + (a - b)^2\right),$$
  and we can take $a$ arbitrary large.
\end{example}

\begin{example}
  \normalfont
  \label{ex:lipt_sum}
  Let us assume that $n \geq 2$ and consider the optimization problem \eqref{eq:main_problem} with $f_1(x) = \frac{b}{2} x^2$  and $f_i(x) = 0$ for $i \in \{2, \cdots, n\},$ where $x \in \R$ and $b \geq 0.$ Then $f(x) = \frac{b}{2 n} x^2,$$$L_{-} = \sup_{x \neq y} \frac{\norm{\nabla f(x) - \nabla f(y)}}{\norm{x - y}} = \frac{b}{n},$$
  $$\frac{1}{n}\sum_{i=1}^n L_i = \frac{1}{n}\sup_{x \neq y} \frac{\norm{\nabla f_1(x) - \nabla f_1(y)}^2}{\norm{x - y}^2} = \frac{b}{n},$$
  and
  $$L_{+} = \sqrt{\sup_{x \neq y} \frac{\frac{1}{n}\sum_{i=1}^n\norm{\nabla f_i(x) - \nabla f_i(y)}^2}{\norm{x - y}^2}} = \frac{b}{\sqrt{n}}.$$
\end{example}

\begin{example}
  \normalfont
  \label{ex:groups}
  Let us consider the optimization problem \eqref{eq:main_problem:group} with $f(x) = \frac{1}{g} \sum_{i=1}^g \frac{1}{m} \sum_{j=1}^{m} f_{ij}(x)$ and $f_{ij}(x) = \frac{b_i}{2} x^2$ for all $i \in [g]$ and $j \in [m]$, where $x \in \R$ and $b_1 \geq 0$ and $b_i = 0$ for all $i \in \{2, \dots, g\}.$
  Then $f(x) = \frac{b_1}{2 g} x^2,$$$L_{-} = \sup_{x \neq y} \frac{\norm{\nabla f(x) - \nabla f(y)}}{\norm{x - y}} = \frac{b_1}{g},$$
  $$L_{\pm}^2 = \sup_{x \neq y} \frac{\frac{1}{g m}\sum_{i=1}^g \sum_{j=1}^m \norm{\nabla f_{ij}(x) - \nabla f_{ij}(y)}^2 - \norm{\nabla f(x) - \nabla f(y)}^2}{\norm{x - y}^2} = \left(\frac{1}{g} - \frac{1}{g^2}\right) b_1^2,$$
  and 
  $$L_{i,\pm}^2 = \sup_{x \neq y} \frac{\frac{1}{m}\sum_{j=m}^n\norm{\nabla f_{ij}(x) - \nabla f_{ij}(y)}^2 - \norm{\nabla f_i(x) - \nabla f_i(y)}^2}{\norm{x - y}^2} = 0 \quad \forall i \in [n].$$

  Substituting the smoothness constants to the complexity $N_{\textnormal{uniform}}$ from Sec~\ref{sec:theorems} and $N_{\textnormal{uniform}}$ from Sec~\ref{sec:sampling_in_sampling}, one can show that
  $$N_{\textnormal{uniform}} = \Theta\left(n + \frac{\Delta_0\max\{\sqrt{n} L_{\pm}, L_{-}\}}{\varepsilon}\right) = \Theta\left(n + \frac{\Delta_0\sqrt{n} b_1}{\varepsilon \sqrt{g}}\right)$$
  and
  $$N_{\textnormal{group}} = \Theta\left(n + \frac{\Delta_0 \max\left\{\sqrt{n} \sqrt{\frac{1}{g}\sum_{i = 1}^g L_{i,\pm}^2}, g L_{-}\right\}}{\varepsilon}\right) = \Theta\left(n + \frac{\Delta_0 b_1}{\varepsilon}\right).$$ The complexity $N_{\textnormal{group}}$ is $\nicefrac{\sqrt{n}}{\sqrt{g}}$ times better than the complexity $N_{\textnormal{uniform}}.$
\end{example}

