			&\quad+\frac{\gamma}{p} \Exp{(1-p)\left\|g^{t}-\nabla f\left(x^{t}\right)\right\|^{2}+(1 - p) \left(\left(A - B\right) L_{+,w}^2 + B L_{\pm,w}^2 \right)\left\|x^{t+1}-x^{t}\right\|^{2}} \\
			&=\Exp{f\left(x^{t}\right)-f^{*}+\left(1 - \frac{p}{2}\right)\frac{\gamma}{p}\left\|g^{t}-\nabla f\left(x^{t}\right)\right\|^{2}-\frac{\gamma}{2}\left\|\nabla f\left(x^{t}\right)\right\|^{2}\right.\\
				&\left.\quad-\left(\frac{1}{2 \gamma}-\frac{L_{-}}{2}-\frac{(1-p)\gamma}{p}\left(\left(A - B\right) L_{+,w}^2 + B L_{\pm,w}^2 \right)\right)\left\|x^{t+1}-x^{t}\right\|^{2}}\\
			&\leq \Exp{f\left(x^{t}\right)-f^{*}+\left(1 - \frac{p}{2}\right)\frac{\gamma}{p}\left\|g^{t}-\nabla f\left(x^{t}\right)\right\|^{2}-\frac{\gamma}{2}\left\|\nabla f\left(x^{t}\right)\right\|^{2}},
		\end{aligned}
	\end{equation*}
	where the last inequality holds due to $\frac{1}{2 \gamma}-\frac{L_{-}}{2}-\frac{(1-p)\gamma}{p}\left(\left(A - B\right) L_{+,w}^2 + B L_{\pm,w}^2 \right) \geq 0$ by choosing stepsize
	$$
	\gamma \leq \left(L_- + \sqrt{\frac{2(1 - p)}{p} \left(\left(A - B\right)L_{+,w}^2 + B L_{\pm,w}^2\right)}\right)^{-1}.
	$$
  Next, using Assumption~\ref{ass:pl} and $\gamma \leq \frac{p}{2\mu}$, we have
  \begin{equation*}
		\begin{aligned}
			&\Exp{f(x^{t+1})-f^{*}+\frac{\gamma}{p}\normsq{g^{t+1}-\nabla f(x^{t+1})}}\\
			&\leq \left(1 - \gamma \mu\right) \Exp{ f\left(x^{t}\right)-f^{*} + \frac{\gamma}{p}\left\|g^{t}-\nabla f\left(x^{t}\right)\right\|^{2}}.
		\end{aligned}
	\end{equation*}
  Unrolling the recursion and considering that $g^0 = \nabla f(x^0),$ we can complete the proof of theorem.
\end{proof}

\section{Derivations of the Parameters for the Samplings}

\subsection{\samplingname{Nice} sampling}\label{subsec:0}
Let $S$ be a random subset uniformly chosen from $[n]$ with a fixed cardinality $\tau$. 
Let us fix $a_1, \dots, a_n \in \R^d.$  A sampling $\samplefunc(a_1, \dots, a_n) \eqdef \frac{1}{n}\sum_{i \in S} \frac{a_i}{p_i}$ is called the \samplingname{Nice} sampling, where $p_i \eqdef \Prob(i \in S).$ 

Let us bound $\Exp{\norm{\samplefunc(a_1, \dots, a_n) - \frac{1}{n}\sum_{i = 1}^n a_i}^2}$ and find parameters from Assumption~\ref{ass:sampling}. Note that $|\samplefunc| = |S| = \tau.$
We introduce auxiliary random variables
\begin{equation*}
	\chi_i\eqdef\begin{cases}
	1&i\in S\\
	0&\text{otherwise.}
	\end{cases}.
\end{equation*}
Due to $p_i = \Prob\left(i \in S\right) = \frac{\tau}{n},$ we have
\begin{equation*}
	\begin{aligned}
		\Exp{\norm{\frac{1}{n}\sum_{i \in S} \frac{a_i}{p_i}}^2}&=\Exp{\normsq{\frac{1}{\tau}\sum_{i=1}^n\chi_i a_i}}\\
		&=\frac{1}{\tau^2}\sum_{i=1}^n\Exp{\normsq{\chi_ia_i}}+\frac{1}{\tau^2}\sum_{i\neq j}\Exp{\inner{\chi_ia_i}{\chi_ja_j}}\\
		&=\frac{1}{\tau^2}\sum_{i=1}^n\Exp{\chi_i}\normsq{a_i}+\frac{1}{\tau^2}\sum_{i\neq j}\Exp{\inner{\chi_i}{\chi_j}}\inner{a_i}{a_j}\\
		&=\frac{1}{n\tau}\sum_{i=1}^n\normsq{a_i}+\frac{\tau-1}{n(n-1)\tau}\sum_{i\neq j}\inner{a_i}{a_j}\\
		&=\frac{1}{n\tau}\sum_{i=1}^n\normsq{a_i}+\frac{\tau-1}{n(n-1)\tau}\left(\normsq{\sum_{i=1}^na_i}-\sum_{i=1}^n\normsq{a_i}\right)\\
		&=\frac{n-\tau}{\tau(n-1)}\frac{1}{n}\sum_{i=1}^n\normsq{a_i}+\frac{\tau-1}{n(n-1)\tau}\normsq{\sum_{i=1}^na_i},
	\end{aligned}
\end{equation*}
where we use $\Exp{\chi_i^2}=\Exp{\chi_i}=\frac{\tau}{n}$ and $\Exp{\chi_i\chi_j}=\frac{\tau(\tau-1)}{n(n-1)},$ when $i\neq j$.

Finally, we have 
\begin{equation*}
	\begin{aligned}
		\Exp{\norm{\frac{1}{n}\sum_{i \in S} \frac{a_i}{p_i} - \frac{1}{n}\sum_{i = 1}^n a_i}^2}&=\Exp{\norm{\frac{1}{n}\sum_{i \in S} \frac{a_i}{p_i}}^2} - \norm{\frac{1}{n}\sum_{i = 1}^n a_i}^2\\
		&=\frac{n-\tau}{\tau(n-1)}\frac{1}{n}\sum_{i=1}^n\normsq{a_i}+\frac{\tau-1}{n(n-1)\tau}\normsq{\sum_{i=1}^na_i}-\normsq{\frac{1}{n}\sum_{i=1}^na_i}\\
		&=\frac{n-\tau}{\tau(n-1)}\left(\frac{1}{n}\sum_{i=1}^n\normsq{a_i}-\normsq{\frac{1}{n}\sum_{i=1}^na_i}\right).
	\end{aligned}
\end{equation*}
Thus we have $A=B=\frac{n-\tau}{\tau(n-1)}$ and $w_i=\frac{1}{n}$ for all $i \in [n].$

\subsection{\samplingname{Independent} sampling}\label{subsec:2}
Let us define i.i.d. random variables
\begin{equation*}
	\chi_i=\begin{cases}
		1&\text{with probability} \ p_i\\
		0&\text{with probability} \ 1-p_i,\\
	\end{cases}.
\end{equation*}
for all $i \in [n]$ and take $S\eqdef\{i \in [n] \,|\, \chi_i = 1\}.$ We now fix $a_1, \dots, a_n \in \R^d.$ A sampling $\samplefunc(a_1, \dots, a_n) \eqdef \frac{1}{n}\sum_{i \in S} \frac{a_i}{p_i}$ is called the \samplingname{Independent} sampling, where $p_i \eqdef \Prob(i \in S).$ 

We get
\begin{equation*}\label{eq:ss}
	\begin{aligned}
		\Exp{\norm{\frac{1}{n}\sum_{i \in S} \frac{a_i}{p_i} - \frac{1}{n}\sum_{i = 1}^n a_i}^2}&=\Exp{\normsq{\frac{1}{n}\sum_{i=1}^n\frac{1}{p_i}\chi_ia_i}}-\normsq{\frac{1}{n}\sum_{i=1}^na_i}\\
    &=\sum_{i=1}^n\frac{\Exp{\chi_i}}{n^2p_i^2}\normsq{a_i}+ \sum_{i \neq j} \frac{\Exp{\chi_i} \Exp{\chi_j}}{n^2 p_i p_j} \inp{a_i}{a_j} -\normsq{\frac{1}{n}\sum_{i=1}^na_i}\\
		&=\sum_{i=1}^n\frac{1}{n^2p_i}\normsq{a_i}+\frac{1}{n^2}\left(\normsq{\sum_{i=1}^na_i}-\sum_{i=1}^n\normsq{a_i}\right)-\normsq{\frac{1}{n}\sum_{i=1}^na_i}\\
		&=\frac{1}{n^2}\sum_{i=1}^n\left(\frac{1}{p_i}-1\right)\normsq{a_i}.
	\end{aligned}
\end{equation*}
Thus we have $A=\frac{1}{\sum_{i=1}^n\frac{p_i}{1-p_i}},$ $B=0$  and $w_i=\frac{\frac{p_i}{1-p_i}}{\sum_{i=1}^n\frac{p_i}{1-p_i}}$ for all $i \in [n].$

\subsection{\samplingname{Importance} and \samplingname{Uniform With Replacement} sampling}\label{subsec:3}
Let us fix $\tau > 0.$ For all $k \in [\tau],$ we define i.i.d. random variables 
\begin{equation*}
	\chi_{k}=\begin{cases}
		1& \text{with probability} \ q_1\\
		2&\text{with probability} \ q_2\\
		\quad &\vdots\\
		n&\text{with probability}\ q_n,
	\end{cases} 
\end{equation*}
where $(q_1, \dots, q_n) \in \mathcal{S}^n$ (simple simplex). 
A sampling 
\begin{equation*}
	\samplefunc(a_1, \dots, a_n) \eqdef \frac{1}{\tau} \sum_{k=1}^{\tau} \frac{a_{\chi_{k}}}{n q_{\chi_{k}}}
\end{equation*} is called the \samplingname{Importance} sampling.
The \samplingname{Importance} sampling reduces to the \samplingname{Uniform With Replacement} sampling when $q_i = \nicefrac{1}{n}$ for all $i \in [n].$ Note that $|\samplefunc| \leq \tau.$ 

Let us bound the variance
\begin{align*}
  &\Exp{\norm{\frac{1}{\tau} \sum_{k=1}^{\tau} \frac{a_{\chi_{k}}}{n q_{\chi_{k}}} - \frac{1}{n}\sum_{i=1}^n a_i}^2} \\
  &= \frac{1}{\tau^2}\sum_{k=1}^{\tau} \Exp{\norm{\frac{a_{\chi_{k}}}{n q_{\chi_{k}}} - \frac{1}{n}\sum_{i=1}^n a_i}^2} + \frac{1}{\tau^2}\sum_{k\neq k'} \Exp{\inp{\frac{a_{\chi_{k}}}{n q_{\chi_{k}}} - \frac{1}{n}\sum_{i=1}^n a_i}{\frac{a_{\chi_{k'}}}{n q_{\chi_{k'}}} - \frac{1}{n}\sum_{i=1}^n a_i}}.
\end{align*}
Using the independents and unbiasedness of the random variables, the last term vanishes and we get
\begin{align*}
  \Exp{\norm{\frac{1}{\tau} \sum_{k=1}^{\tau} \frac{a_{\chi_{k}}}{n q_{\chi_{k}}} - \frac{1}{n}\sum_{i=1}^n a_i}^2} &= \frac{1}{\tau^2}\sum_{k=1}^{\tau} \Exp{\norm{\frac{a_{\chi_{k}}}{n q_{\chi_{k}}} - \frac{1}{n}\sum_{i=1}^n a_i}^2} \\
  &\overset{\eqref{auxiliary:variance_decomposition}}{=} \frac{1}{\tau^2}\sum_{k=1}^{\tau} \Exp{\norm{\frac{a_{\chi_{k}}}{n q_{\chi_{k}}}}^2} - \frac{1}{\tau} \norm{\frac{1}{n}\sum_{i=1}^n a_i}^2 \\
  &= \frac{1}{\tau} \sum_{i=1}^n q_i \norm{\frac{a_{i}}{n q_{i}}}^2 - \frac{1}{\tau} \norm{\frac{1}{n}\sum_{i=1}^n a_i}^2\\
  &= \frac{1}{\tau} \left(\frac{1}{n}\sum_{i=1}^n \frac{1}{n q_i} \norm{a_{i}}^2 - \norm{\frac{1}{n}\sum_{i=1}^n a_i}^2\right).
\end{align*}
Thus we have $A=B=\frac{1}{\tau},$ and $w_i=q_i$ for all $i \in [n].$

\subsection{\samplingname{Extended Nice} sampling}\label{subsec:1}
In this section, we analyze the extension of \samplingname{Nice} sampling. First, we $l_i$ times repeat each vector $a_i$, then we use the \samplingname{Nice} sampling. We define

\begin{equation*}
	\tilde{a}_i\eqdef\begin{cases}
		\frac{\sum_{j=1}^nl_j}{nl_1}a_1&1\leq i\leq l_1\\
		\frac{\sum_{j=1}^nl_j}{nl_2}a_2&l_1+1\leq i\leq l_1+l_2\\
		\quad&\vdots\\
		\frac{\sum_{j=1}^nl_j}{nl_n}a_n&\sum_{j=1}^{n-1}l_j\leq i\leq \sum_{j=1}^nl_j,\\
	\end{cases},
\end{equation*}
where $a_i \in \R^d$ and $l_i \geq 1$ for all $i \in [n].$
Then we have
\begin{equation*}
	\frac{1}{n}\sum_{i=1}^n a_i(x)=\frac{1}{N}\sum_{i=1}^{N}\tilde{a}_i(x),
\end{equation*}
where  $N\eqdef\sum_{j=1}^nl_j$. Also, we denote $N_k \eqdef \sum_{j=1}^kl_j.$

For some $\tau > 0,$ we apply the \samplingname{Nice} sampling method:
\begin{equation*}
	\samplefunc(a_1, \dots, a_n) \eqdef \frac{1}{N}\sum_{i \in S} \frac{\tilde{a}_i}{p_i} = \sum_{i=1}^N\frac{1}{\tau}\chi_i\tilde{a}_i,
\end{equation*}
where \begin{equation*}
	\chi_i=\begin{cases}
		1&i\in S\\
		0&\text{otherwise}
	\end{cases},\quad p_i = \Prob\left(i \in S\right),
\end{equation*}
and $S$ is a random set with cardinality $\tau$ from $[N]$. The sampling $\samplefunc(a_1, \dots, a_n)$ is called the \samplingname{Extended Nice} sampling.

We now ready to bound the variance. Using the results for the \samplingname{Nice} sampling, we obtain
\begin{align*}
		&\Exp{\norm{\samplefunc(a_1, \dots, a_n) - \frac{1}{n}\sum_{i=1}^n a_i(x)}^2}\\
    &=\Exp{\norm{\samplefunc(a_1, \dots, a_n) - \frac{1}{N}\sum_{i=1}^{N}\tilde{a}_i(x)}^2}\\
    &=\frac{n-\tau}{\tau(n-1)}\frac{1}{N}\sum_{i=1}^N\normsq{\tilde{a}_i}-\frac{n-\tau}{\tau(n-1)}\normsq{\frac{1}{N}\sum_{i=1}^N\tilde{a}_i}\\
		&=\frac{n-\tau}{\tau(n-1)}\left(\frac{1}{N}\left(\frac{N}{nl_1}\right)^2\sum_{i=1}^{N_1}\normsq{{a}_1}+\frac{1}{N}\left(\frac{N}{nl_2}\right)^2\sum_{i=N_1+1}^{N_2}\normsq{{a}_2}\right.\\
		&\left.\quad+\cdots+\frac{1}{N}\left(\frac{N}{nl_n}\right)^2\sum_{i=N_{n-1}+1}^{N}\normsq{{a}_n}\right)-\frac{n-\tau}{\tau(n-1)}\normsq{\frac{1}{n}\sum_{i=1}^na_i}\\
		&={\frac{n-\tau}{\tau(n-1)}{\left(\frac{N}{nl_1}\frac{1}{n}\normsq{a_1}+\frac{N}{nl_2}\frac{1}{n}\normsq{a_2}+\cdots+\frac{N}{nl_n}\frac{1}{n}\normsq{a_n}\right)}-\frac{n-\tau}{\tau(n-1)}\normsq{\frac{1}{n}\sum_{i=1}^na_i}}\\
		&{=\frac{n-\tau}{\tau(n-1)}\left(\sum_{i=1}^n\frac{1}{n^2w_i}\normsq{a_i}\right)-\frac{n-\tau}{\tau(n-1)}\normsq{\frac{1}{n}\sum_{i=1}^na_i}}
\end{align*}
where $w_i=\frac{l_i}{N}$. Thus we have $A=B = \frac{n-\tau}{\tau(n-1)}$ and  $w_i=\frac{l_i}{N}$ for $i \in [n].$

\section{The Optimal Choice of $w_i$}
\label{sec:optimal_weights}
Let us consider $L_{+,w}^2$ and $L_{\pm,w}^2.$ In Sec~\ref{sec:assumptions}, we show that one can take $L_{+,w}^2 = L_{\pm,w}^2 = \frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i} L_i^2.$ Let us minimize $\frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i} L_i^2$ with respect to the weights $w_i$ such that $w_1, \dots, w_n \geq 0$ and $\sum_{i=1}^n w_i = 1$. Using the method of Lagrange multipliers, we can construct a Lagrangian
\begin{equation*}
	\cL(w,\lambda)\eqdef\frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i} L_i^2-\lambda \left(\sum_{i=1}^nw_i-1\right).
\end{equation*}
Next, we calculate partial derivatives
\begin{align*}
	&\frac{\partial\cL}{\partial w_i}=-\frac{1}{n^2w_i^2}L_i^2-\lambda=0 \forall i \in [n]
\end{align*}
and get
\begin{equation*}
	w_i^2=-\frac{L_i^2}{n^2\lambda}.
\end{equation*}
Using $\sum_{i=1}^n w_i = 1,$ we can show that the weights $w_i^*=\frac{L_i}{\sum_{i=1}^nL_i}$ are the solutions of the minimization problem. Moreover, 
\begin{equation*}
\frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i^*} L_i^2 = \left(\frac{1}{n}\sum_{i=1}^nL_i\right)^2.
\end{equation*}

