\section{Missing Proofs: The Composition of Samplings}

\begin{restatable}{lemma}{LEMMASAMPLINGINSAMPLING}
  \label{lemma:sampling}
  Let us assume that a random sampling function $\samplefunc$ satisfies Assumption~\ref{ass:sampling} with some $A, B$ and weights $w_i,$ and a random sampling function $\samplefunc_i$ satisfy Assumption~\ref{ass:sampling} with some $A_i, B_i$ and weights $w_{ij}$ for all $i \in [n].$ Moreover, $B \leq 1.$ Then
  \begin{align*}
    &\Exp{\norm{\samplefunc\left(\samplefunc_1\left(a_{11}, \dots, a_{1 m_1}\right), \dots, \samplefunc_n\left(a_{n1}, \dots, a_{n m_n}\right)\right) - \frac{1}{n}\sum_{i = 1}^n \left(\frac{1}{m_i} \sum_{j=1}^{m_i} a_{ij}\right)}^2} \\
    &\leq \frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left(\frac{A_i}{m_i}\sum_{j = 1}^{m_i} \frac{1}{m_i w_{ij}}\norm{a_{ij}}^2 - B_i \norm{\frac{1}{m_i} \sum_{j=1}^{m_i} a_{ij}}^2\right) \\
    &\quad + \frac{A}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{\frac{1}{m_i} \sum_{j=1}^{m_i} a_{ij}}^2 - B \norm{\frac{1}{n}\sum_{i = 1}^n \left(\frac{1}{m_i} \sum_{j=1}^{m_i} a_{ij}\right)}^2,
  \end{align*}
  where $a_{ij} \in \R^d$ for all $j \in [m_i]$ and $i \in [n].$
\end{restatable}

\begin{proof}
  We denote $\widehat{a}_i \eqdef \samplefunc_i\left(a_{i1}, \dots, a_{i m_i}\right)$ and $a_i \eqdef \frac{1}{m_i}\sum_{j=1}^{m_i} a_{ij}.$ Using \eqref{auxiliary:variance_decomposition}, we have
  \begin{align*}
    &\Exp{\norm{\samplefunc\left(\widehat{a}_1, \dots, \widehat{a}_n\right) - \frac{1}{n}\sum_{i = 1}^n a_i}^2} \\
    &=\Exp{\ExpSub{S}{\norm{\samplefunc\left(\widehat{a}_1, \dots, \widehat{a}_n\right) - \frac{1}{n}\sum_{i = 1}^n a_i}^2}} \\
    &=\Exp{\ExpSub{S}{\norm{\samplefunc\left(\widehat{a}_1, \dots, \widehat{a}_n\right) - \frac{1}{n}\sum_{i = 1}^n \widehat{a}_i}^2}} + \Exp{\norm{\frac{1}{n}\sum_{i = 1}^n \widehat{a}_i - \frac{1}{n}\sum_{i = 1}^n a_i}^2}.
  \end{align*}
  Next, using Assumption~\ref{ass:sampling} for the sampling $\samplefunc,$ we get
  \begin{align*}
    &\Exp{\norm{\samplefunc\left(\widehat{a}_1, \dots, \widehat{a}_n\right) - \frac{1}{n}\sum_{i = 1}^n a_i}^2} \\
    &\leq A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\Exp{\norm{\widehat{a}_i}^2} - B \Exp{\norm{\frac{1}{n}\sum_{i = 1}^n \widehat{a}_i}^2} \\
    &\quad + \Exp{\norm{\frac{1}{n}\sum_{i = 1}^n \widehat{a}_i - \frac{1}{n}\sum_{i = 1}^n a_i}^2}.
  \end{align*}
  Due to \eqref{auxiliary:variance_decomposition}, we obtain
  \begin{align*}
    &\Exp{\norm{\samplefunc\left(\widehat{a}_1, \dots, \widehat{a}_n\right) - \frac{1}{n}\sum_{i = 1}^n a_i}^2} \\
    &\leq A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\Exp{\norm{\widehat{a}_i - a_i}^2} + A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{a_i}^2 \\
    &\quad - B \Exp{\norm{\frac{1}{n}\sum_{i = 1}^n \widehat{a}_i - \frac{1}{n}\sum_{i = 1}^n a_i}^2} - B \norm{\frac{1}{n}\sum_{i = 1}^n a_i}^2  \\
    &\quad + \Exp{\norm{\frac{1}{n}\sum_{i = 1}^n \widehat{a}_i - \frac{1}{n}\sum_{i = 1}^n a_i}^2} \\
    &= A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\Exp{\norm{\widehat{a}_i - a_i}^2} + A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{a_i}^2 \\
    &\quad + (1 - B) \Exp{\norm{\frac{1}{n}\sum_{i = 1}^n \widehat{a}_i - \frac{1}{n}\sum_{i = 1}^n a_i}^2} - B \norm{\frac{1}{n}\sum_{i = 1}^n a_i}^2 \\
    &= A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\Exp{\norm{\widehat{a}_i - a_i}^2} + A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{a_i}^2 \\
    &\quad + \frac{(1 - B)}{n^2} \sum_{i=1}^n \Exp{\norm{\widehat{a}_i - a_i}^2} - B \norm{\frac{1}{n}\sum_{i = 1}^n a_i}^2 \\
    &= \frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\Exp{\norm{\widehat{a}_i - a_i}^2} + A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{a_i}^2 - B \norm{\frac{1}{n}\sum_{i = 1}^n a_i}^2. 
  \end{align*}
  Using Assumption~\ref{ass:sampling} for the samplings $\samplefunc_i,$ we have
  \begin{align*}
    &\Exp{\norm{\samplefunc\left(\widehat{a}_1, \dots, \widehat{a}_n\right) - \frac{1}{n}\sum_{i = 1}^n a_i}^2} \\
    &\leq \frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left(A_i \frac{1}{m_i}\sum_{j = 1}^{m_i} \frac{1}{m_i w_{ij}}\norm{a_{ij}}^2 - B_i \norm{a_i}^2\right) \\
    &\quad + A \frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{a_i}^2 - B \norm{\frac{1}{n}\sum_{i = 1}^n a_i}^2.
  \end{align*}
\end{proof}

\THEOREMCONVERGENCEPAGECOMPOSITION*

\begin{proof}
  We start with the estimation of the variance of the noise:
	\begin{align*}
		&\Exp{\norm{g^{t+1} - \nabla f(x^{t+1})}^2} \\
		&= (1 - p) \Exp{\norm{g^t + \samplefunc\left(\left\{\samplefunc_i\left(\{\nabla f_{ij}(x^{t+1}) - \nabla f_{ij}(x^{t})\}_{j=1}^{m_i}\right)\right\}_{i=1}^n\right) - \nabla f(x^{t+1})}^2} \\
		&= (1 - p) \norm{\samplefunc\left(\left\{\samplefunc_i\left(\{\nabla f_{ij}(x^{t+1}) - \nabla f_{ij}(x^{t})\}_{j=1}^{m_i}\right)\right\}_{i=1}^n\right) - \left(\nabla f(x^{t+1}) - \nabla f(x^{t})\right)}^2 + (1 - p) \norm{g^t - \nabla f(x^{t})}^2,
	\end{align*}
  where we used the unbiasedness of the composition of samplings.
	Using Lemma~\ref{lemma:sampling}, we have
	\begin{align*}
		&\Exp{\norm{g^{t+1} - \nabla f(x^{t+1})}^2} \\
		&\leq (1 - p) \left(\frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left(\frac{A_i}{m_i}\sum_{j = 1}^{m_i} \frac{1}{m_i w_{ij}}\norm{\nabla f_{ij}(x^{t+1}) - \nabla f_{ij}(x^{t})}^2 - B_i \norm{\nabla f_{i}(x^{t+1}) - \nabla f_{i}(x^{t})}^2\right) \right.\\
    &\left.\quad + \frac{A}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{\nabla f_{i}(x^{t+1}) - \nabla f_{i}(x^{t})}^2 - B \norm{\nabla f(x^{t+1}) - \nabla f(x^{t})}^2\right)\\
		&\quad + (1 - p) \norm{g^t - \nabla f(x^{t})}^2.
	\end{align*}
	Using Definitions~\ref{def:weighted_local_lipschitz_constant}, \ref{def:weighted_hessian_varaince}, \ref{def:weighted_local_lipschitz_constant:local} and \ref{def:weighted_hessian_varaince:local}, we get
	\begin{align*}
			&\Exp{\norm{g^{t+1} - \nabla f(x^{t+1})}^2} \\
			&\leq (1 - p) \left(\frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left(\frac{A_i - B_i}{m_i}\sum_{j = 1}^{m_i} \frac{1}{m_i w_{ij}}\norm{\nabla f_{ij}(x^{t+1}) - \nabla f_{ij}(x^{t})}^2 \right.\right.\\
      &\left.\left.+\quad B_i \left(\frac{1}{m_i}\sum_{j = 1}^{m_i} \frac{1}{m_i w_{ij}}\norm{\nabla f_{ij}(x^{t+1}) - \nabla f_{ij}(x^{t})}^2 - \norm{\nabla f_{i}(x^{t+1}) - \nabla f_{i}(x^{t})}^2\right)\right) \right.\\
      &\left.\quad + \frac{A - B}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{\nabla f_{i}(x^{t+1}) - \nabla f_{i}(x^{t})}^2 \right.\\
      &\left.\quad+ B\left(\frac{1}{n}\sum_{i = 1}^n \frac{1}{n w_i}\norm{\nabla f_{i}(x^{t+1}) - \nabla f_{i}(x^{t})}^2 - \norm{\nabla f(x^{t+1}) - \nabla f(x^{t})}^2\right)\right) \\
      &\quad + (1 - p) \norm{g^t - \nabla f(x^{t})}^2 \\
      &\leq (1 - p) \left(\frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left((A_i - B_i) L_{i,+,w_i}^2 + B_i L_{i,\pm,w_i}^2\right) + (A - B)L_{+,w}^2 + B L_{\pm,w}^2\right) \norm{x^{t+1} - x^t}^2 \\
      &\quad + (1 - p) \norm{g^t - \nabla f(x^{t})}^2.
  \end{align*}
  From this point the proof of theorem repeats the proof of Thm~\ref{theorem:pageab} with $$\frac{1}{n}\sum_{i = 1}^n \left(\frac{A}{n w_i} + \frac{(1 - B)}{n}\right)\left((A_i - B_i) L_{i,+,w_i}^2 + B_i L_{i,\pm,w_i}^2\right) + (A - B)L_{+,w}^2 + B L_{\pm,w}^2$$ instead of $$\left(A - B\right) L_{+,w}^2 + B L_{\pm,w}^2.$$
\end{proof}


