\paragraph{Construction of synthetic optimization problem.} As it has mentioned in the main part we have specialized our general formulation for finite sum minimization 
$f(x) \eqdef \frac{1}{n}\sum_{i=1}^n f_i(x)$ for a particular case when $f_i(x) =\|{a_i}^\top x - b\|^2 + \lambda \cdot r(x)$, where $\lambda \ge 0$ is parameter of a regularization, and $r(x)$ is twice continuous differentiable function and L smooth with smoothness constant $L_r$. In that case $\nabla f_i(x) = (2 {a_i} {a_i}^\top x - 2 a_i b_i) + \lambda \nabla r(x)$ and $\nabla^2 f_i(x) = 2 \cdot a_i  {a_i}^\top + \lambda \nabla^2 r(x)$.

Under assumptions on $r(x)$ the $\nabla^2 f_i(x)$ is symmetric matrix and we can compute $L_{f_i}$ in the following way: $$L_{f_i} = \lambda_{\max}(\nabla^2 f_i(x)) = \|\nabla^2 f_i(x)\|_2 = \|2\cdot a_i  {a_i}^\top + \lambda \nabla^2 r(x)\| \le 2 \langle {a_i}, a_i \rangle + \lambda L_{r}$$

Let's introduce block matrix $A$ and block vector $b$ in the following standard way:
\[
A \eqdef
\begin{bmatrix}
	a_{1}^\top \\
	\vdots \\
	a_{n}^\top
\end{bmatrix},
\quad \text{and} \quad 
b \eqdef
\begin{bmatrix}
	b_{1} \\
	\vdots \\
	b_{n}
\end{bmatrix}
\eqdef 0.
\]
\begin{eqnarray*}
	f(x) = \sum_{i=1}^{n}f_i(x) = \frac{1}{n}\|Ax-b\|^2 + \lambda \cdot r(x) = \frac{1}{n} \left( x^\top A^\top A x - 2 \langle A x, b \rangle + {b}^\top b \right) + \lambda \cdot r(x) \\= \frac{1}{2} x^\top \left({\frac{2}{n}}A^\top A\right) x - \dfrac{2}{n} \langle Ax, b \rangle + \dfrac{1}{n} b^\top b+ \lambda \cdot r(x).
\end{eqnarray*}

And therefore:
\begin{eqnarray*}
	\nabla f(x) = \left({\frac{2}{n}}A^\top A\right) x - \frac{2}{n} \cdot A^\top b + \lambda \cdot \nabla r(x),\\
	\nabla^2 f(x) = \left({\frac{2}{n}}A^\top A\right) + \lambda \cdot \nabla^2 r(x).
\end{eqnarray*}

\paragraph{Derivation of need parameters.} For that specific problem let's derive the need constants for evaluating step size. The $L_{-}$ constant Eq. \ref{ass:lipschitz_constant} defined as: $\norm{\nabla f(x) - \nabla f(y)} \leq L_{-} \norm{x - y}, \forall x, y \in \R^d.$ The $L_{-}$ constant can be computed in the following way:
\begin{eqnarray*}
\| \left(({\frac{2}{n}}A^\top A) x - 2\cdot A^\top b + \lambda \cdot \nabla r(x)\right) - \left( ({\frac{2}{n}}A^\top A) y - 2\cdot A^\top b + \lambda \cdot \nabla r(y) \right)\|  \\ =
\| ({\frac{2}{n}}A^\top A) (x-y) + \lambda(\nabla r(x) - \nabla r(y)) \| \le
\left({\frac{2}{n}}\|A^\top A \| +  \lambda \cdot L_r\right) \|x-y\|
\end{eqnarray*}

For that problem class we have: $L_{-} \ge \left({\frac{2}{n}}\|A^\top A \| +  \lambda \cdot L_r\right)$.

Next we need to compute $L_{+,w}$ defined in Eq. \ref{ass:weighted_local_lipschitz_constant} as $\frac{1}{n} \sum_{i=1}^n \frac{1}{n w_i}\norm{\nabla f_i(x) - \nabla f_i(y)}^2 \leq L_{+,w}^2 \norm{x - y}^2$. The $L_{+,w}$ constant can be computed in the following way:
