\section{Artificial Quadratic Optimization Tasks}

In this section, we provide algorithms that we use to generate artificial optimization tasks for experiments. Algorithm~\ref{algorithm:matrix_generation} and Algorithm~\ref{algorithm:matrix_generation_l_i} allow us to control the smoothness constants $L_{\pm}$ and $L_{i},$ accordingly, via the noise scales.
\begin{algorithm}
  \caption{Generate quadratic optimization task with controlled $L_{\pm}$ (homogeneity)}
  \begin{algorithmic}[1]
  \label{algorithm:matrix_generation}
  \STATE \textbf{Parameters:} number nodes $n$, dimension $d$, regularizer $\lambda$, and noise scale $s$.
  \FOR{$i = 1, \dots, n$}
  \STATE Generate random noises $\nu_i^s = 1 + s \xi_i^s$ and $\nu_i^b = s \xi_i^b,$ i.i.d. $\xi_i^s, \xi_i^b \sim \textnormal{NormalDistribution}(0, 1)$
  \STATE Take vector $b_i = \frac{\nu_i^s}{4}(-1 + \nu_i^b, 0, \cdots, 0) \in \R^{d}$
  \STATE Take the initial tridiagonal matrix
  \[\mA_i = \frac{\nu_i^s}{4}\left( \begin{array}{cccc}
    2 & -1 & & 0\\
    -1 & \ddots & \ddots & \\
    & \ddots & \ddots & -1 \\
    0 & & -1 & 2 \end{array} \right) \in \R^{d \times d}\]
  \ENDFOR
  \STATE Take the mean of matrices $\mA = \frac{1}{n}\sum_{i=1}^n \mA_i$
  \STATE Find the minimum eigenvalue $\lambda_{\min}(\mA)$
  \FOR{$i = 1, \dots, n$}
  \STATE Update matrix $\mA_i = \mA_i + (\lambda - \lambda_{\min}(\mA)) \mI$
  \ENDFOR
  \STATE Take starting point $x^0 = (\sqrt{d}, 0, \cdots, 0)$
  \STATE \textbf{Output:} matrices $\mA_1, \cdots, \mA_n$, vectors $b_1, \cdots, b_n$, starting point $x^0$
  \end{algorithmic}
\end{algorithm}

\begin{algorithm}
  \caption{Generate quadratic optimization task with controlled $L_i$}
  \begin{algorithmic}[1]
  \label{algorithm:matrix_generation_l_i}
  \STATE \textbf{Parameters:} number nodes $n$, dimension $d$, regularizer $\lambda$, and noise scale $s$.
  \FOR{$i = 1, \dots, n$}
  \STATE Generate random noises $\nu_i^s = 1 + s \xi_i^s,$ where i.i.d. $\xi_i^s \sim \textnormal{ExponentialDistribution}(1.0)$
  \STATE Generate random noises $\nu_i^b = s \xi_i^b,$ i.i.d. $\xi_i^b \sim \textnormal{NormalDistribution}(0, 1)$
  \STATE Take vector $b_i = (-\frac{1}{4} + \nu_i^b, 0, \cdots, 0) \in \R^{d}$
  \STATE Take the initial tridiagonal matrix
  \[\mA_i = \frac{\nu_i^s}{4}\left( \begin{array}{cccc}
    2 & -1 & & 0\\
    -1 & \ddots & \ddots & \\
    & \ddots & \ddots & -1 \\
    0 & & -1 & 2 \end{array} \right) \in \R^{d \times d}\]
  \ENDFOR
  \STATE Take starting point $x^0 = (\sqrt{d}, 0, \cdots, 0)$
  \STATE \textbf{Output:} matrices $\mA_1, \cdots, \mA_n$, vectors $b_1, \cdots, b_n$, starting point $x^0$
  \end{algorithmic}
\end{algorithm}

