\begin{document}


\maketitle


\begin{abstract}

    In practical distributed systems, workers are typically not homogeneous, and due to differences in hardware configurations and network conditions, can have highly varying processing times. We consider smooth nonconvex finite-sum (empirical risk minimization) problems in this setup and introduce a new parallel method, \algname{Freya PAGE}, designed to handle arbitrarily heterogeneous and asynchronous computations. By being robust to ``stragglers'' and adaptively ignoring slow computations, \algname{Freya PAGE} offers significantly improved \emph{time complexity} guarantees compared to all previous methods, including \algname{Asynchronous SGD}, \algname{Rennala SGD}, \algname{SPIDER}, and \algname{PAGE}, while requiring weaker assumptions. The algorithm relies on novel generic stochastic gradient collection strategies with theoretical guarantees that can be of interest on their own, and may be used in the design of future optimization methods. Furthermore, we establish a lower bound for smooth nonconvex finite-sum problems in the asynchronous setup, providing a fundamental time complexity limit. This lower bound is tight and demonstrates the optimality of \algname{Freya PAGE} in the large-scale regime, i.e., when $\sqrt{m} \geq n,$ where $n$ is \# of workers, and $m$ is \# of data samples.

\end{abstract}

\section{Introduction}\label{sec:intro}

In real-world distributed systems used for large-scale machine learning tasks, it is common to encounter device heterogeneity and variations in processing times among different computational units. These can stem from GPU computation delays, disparities in hardware configurations, network conditions, and other factors, resulting in different computational capabilities and speeds across devices \citep{chen2016revisiting, tyurin2023optimal}. As a result, some clients may execute computations faster, while others experience delays or even fail to participate in the training altogether.

Due to the above reasons, we aim to address the challenges posed by device heterogeneity in the context of solving finite-sum nonconvex optimization problems of the form
\begin{align}\label{eq:problem}
    \textstyle \min\limits_{x\in \R^d} \brac{f(x) \eqdef \frac{1}{m} \sum\limits_{i=1}^m f_i(x)},
\end{align}
where $f_i: \R^d \rightarrow \R$ can be viewed as the loss of a machine learning model $x$ on the $i$\textsuperscript{th} example in a training dataset with $m$ samples. Our goal is to find an $\varepsilon$-stationary point, i.e., a (possibly random) point $\hat{x}$ such that $\mathbb{E}[\|\nabla f(\hat{x})\|^2] \leq \varepsilon$.
We focus on the homogeneous distributed setup:
\begin{itemize}
    \item there are $n$ \emph{workers}/\emph{clients}/\emph{devices} able to work in parallel,
    \item each worker has access to stochastic gradients $\nabla f_j$, $j \in [m]$,
    \item worker $i$ calculates $\nabla f_j(\cdot)$ in less or equal to $\tau_i \in [0, \infty]$ seconds for all $i \in [n], j \in [m].$
\end{itemize}
Without loss of generality, we assume that $\tau_1\leq\ldots\leq\tau_n$. One can think of $\tau_i \in [0, \infty]$ as an upper bound on the computation time rather than a fixed deterministic time. 
Looking ahead, iteration complexity can be established even if $\tau_i = \infty$ for all $i \in [n]$ (Theorem~\ref{thm:page_rate}). We also provide results where the bounds $\{\tau_i^k\}$ are dynamic and change with every iteration $k$ (Section~\ref{sec:time_var_times}). For simplicity of presentation, however, we assume that $\tau_i^k = \tau_i$ for $i \in [n], k \geq 0$, unless explicitly stated otherwise.

\subsection{Assumptions}\label{sec:assumptions}

We adopt two weak assumptions, which are standard for the problem \eqref{eq:problem} \citep{fang2018spider}.
\begin{assumption}\label{as:smooth_lower_bdd}
    The function $f$ is $L_-$-smooth and lower-bounded by $f^* \in \R$.
\end{assumption}
\begin{assumption}\label{as:L+}
    $\exists \, L_+ \geq 0$ such that $\frac{1}{m} \sum\limits_{i=1}^{m} \norm{\nabla f_i(x) - \nabla f_i(y)}^2 \leq L_+^2 \norm{x - y}^2\, \forall x,y\in\R^d.$
\end{assumption}
We also consider Assumption~\ref{as:L_pm}. Note that this assumption does not restrict the class of considered functions $\{f_i\}.$
Indeed, if Assumption~\ref{as:L+} holds with $L_{+},$ then Assumption~\ref{as:L_pm} holds with some $L_{\pm} \leq L_{+}$. If one only wants to rely on Assumptions~\ref{as:smooth_lower_bdd} and \ref{as:L+}, it is sufficient to take $L_{\pm} = L_{+}$. However, Assumption~\ref{as:L_pm} enables us to derive sharper rates, since $L_{\pm}$ can be small or even $0$, even if $L_-$ and $L_{+}$ are large \citep{szlendak2021permutation,tyurin2022sharper,kovalev2022optimal}.
\begin{assumption}[Hessian variance \citep{szlendak2021permutation}]\label{as:L_pm}
    There exists $L_{\pm} \geq 0$ such that
    \begin{align*}
        \textstyle \frac{1}{m} \sum\limits_{i=1}^m \norm{\nabla f_i(x) - \nabla f_i(y) - \left(\nabla f(x) - \nabla f(y)\right)}^2 \leq L^2_{\pm} \norm{x-y}^2
        \qquad \forall x, y \in \R^d.
    \end{align*}
\end{assumption}


\subsection{Gradient oracle complexities}\label{sec:sync_vr}

Iterative algorithms are traditionally evaluated based on their \emph{gradient complexity}. Let us present a brief overview of existing theory.
The classical result of Gradient Descent (\algname{GD}) says that in the smooth nonconvex regime, the number of oracle calls needed to solve problem~\eqref{eq:problem} is $\cO(m\varepsilon^{-1})$ because \algname{GD} converges in $\cO(\varepsilon^{-1})$ iterations, and calculates the full gradient $\nabla f = \nicefrac{1}{m} \sum_{i=1}^m \nabla f_i$ in each iteration.
This was improved to $\cO(m + m^{\nicefrac{2}{3}} \varepsilon^{-1})$ by several \emph{variance-reduced} methods, including \algname{SVRG} and \algname{SCSG} \citep{allen2016variance, reddi2016stochastic, lei2017non, horvath2019nonconvex}.
Since then, various other algorithms, such as \algname{SNVRG}, \algname{SARAH}, \algname{SPIDER}, \algname{SpiderBoost}, \algname{PAGE} and their variants, have been developed \citep{fang2018spider, wang2019spiderboost, nguyen2017sarah, li2021page, zhou2020stochastic, horvath2022adaptivity}. These methods achieve a gradient complexity of $\cO(m + \sqrt{m} \varepsilon^{-1})$, matching the lower bounds \citep{fang2018spider,li2021page}.

That said, in practical scenarios, what often truly matters is the \emph{time complexity} rather than the \emph{gradient complexity} \citep{tyurin2023optimal}. Although the latter metric serves as a natural benchmark for sequential methods, it seems ill-suited in the context of parallel methods. %Indeed, differences in processing speeds across devices can significantly impact the performance of parallel algorithms.




\subsection{Some previous time complexities}
\label{sec:previous_compl}
Let us consider some examples to provide intuition about time complexities for problem \eqref{eq:problem}.

\textbf{\algname{GD} with $1$ worker (\algname{Hero GD}).} In principle, each worker can solve the problem on their own. Hence, one approach would be to select the fastest client (assuming it is known) and delegate the task to them exclusively.
A well-known result says that for $L_-$-smooth objective function $f$ (Assumption~\ref{as:smooth_lower_bdd}), \algname{GD} converges in $\delta^0L_-\varepsilon^{-1}$ iterations, where $\delta^0 \eqdef f(x^0)-f^*,$ and $x^0$ is the starting point. Since at each iteration the method computes $m$ gradients $\nabla f_i(\cdot)$, $i\in[m]$, the time required to find an $\varepsilon$-stationary point is $\delta^0L_-\varepsilon^{-1} \times m \tau_1$ seconds.

\textbf{\algname{GD} with $n$ workers and equal data allocation (\algname{Soviet GD}).} The above strategy leaves the remaining $n-1$ workers idle, and thus potentially useful computing resources are wasted. A common approach is to instead divide the data into $n$ equal parts and assign one such part to each worker, so that each has to compute $\nicefrac{m}{n}$ gradients (assuming for simplicity that $m$ is divisible by $n$). Since at each iteration the strategy needs to wait for the slowest worker, the total time is $\delta^0L_-\varepsilon^{-1} \times \nicefrac{m \tau_n}{n}$. Depending on the relationship between $\tau_1$ and $\nicefrac{\tau_n}{n}$, this could be more efficient or less efficient compared to \algname{Hero~GD}. This shows that the presence of stragglers can eliminate the potential speedup expected from parallelizing the training \citep{dutta2018slow}.

\textbf{\algname{SPIDER}/\algname{PAGE} with $1$ worker or $n$ workers and equal data allocation (\algname{Hero PAGE} and \algname{Soviet PAGE}).}
As mentioned in Section~\ref{sec:sync_vr}, \algname{SPIDER}/\algname{PAGE} can have better \emph{gradient complexity} guarantees than \algname{GD}. Using the result of \citet{li2021page}, the equal data allocation strategy with $n$ workers leads to the time complexity of
\begin{align}
    \label{eq:page_time}
    \textstyle T_{\textnormal{Soviet PAGE}} \eqdef \Theta\left(\tau_n \max\left\{\frac{m}{n}, 1\right\} + \tau_n \frac{\delta^0 \max\{L_-, L_{\pm}\}}{\varepsilon}\max\left\{\frac{\sqrt{m}}{n}, 1\right\} \right)
\end{align}
seconds. We refer to this method as \algname{Soviet PAGE}. In practical regimes, when $\varepsilon$ is small and $L_- \approx L_{\pm}$, this complexity can be $\sqrt{m}$ better than that of \algname{GD}. Running \algname{PAGE} on the fastest worker (which we will call \algname{Hero PAGE}), we instead get the time complexity $T_{\textnormal{Hero PAGE}}~\eqdef~\Theta\left(\tau_1 m + \tau_1 \nicefrac{\delta^0}{\varepsilon} \sqrt{m}\right).$

Given these examples, the following question remains unanswered: what is the best possible time complexity in our setting? This paper aims to answer this question.

