\section{The Time Complexity Guarantees of Algorithms~\ref{algorithm:ga_asynch_main_diff} and \ref{algorithm:ga_asynch_batch}}

In addition to \algname{ComputeBatchDifference} (Algorithm~\ref{algorithm:ga_asynch_main_diff}) introduced in the main part, we also analyze \algname{ComputeBatch} (Algorithm~\ref{algorithm:ga_asynch_batch}) that is similar to \algname{ComputeBatchDifference}, but calculates a minibatch of stochastic gradients $\nabla f_i(x)$ instead of stochastic gradient differences $\nabla f_i(x) - \nabla f_i(y).$

\begin{algorithm}[h]
    \centering
    \caption{\algname{ComputeBatch}($S$, $x$)}
    \label{algorithm:ga_asynch_batch}
    \begin{algorithmic}[1]
    \State \textbf{Input:} batch size $S\in\N$, point $x\in\R^d$
    \State Init $g=0\in\R^d$
    \State Broadcast $x$ to all workers
    \State For each worker, sample $j$ from $[m]$ (uniformly) and ask it to calculate $\nabla f_j(x)$
        \For{$i = 1, 2, \ldots, S$}
            \State Wait for $\nabla f_p(x)$ from a worker
            \State $g \gets g + \frac{1}{S} \nabla f_p(x)$
            \State Sample $j$ from $[m]$ (uniformly)
            and ask this worker to calculate $\nabla f_j(x)$
        \EndFor
        \State Return $g$
    \end{algorithmic}
\end{algorithm}

\THMBATHDIFF*

\begin{proof}
    Let
    \begin{align*}
        t = 4 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S + j)}.
    \end{align*}
    As soon as some worker finishes calculating the stochastic gradient difference, it immediately starts computing the difference of the next pair. Hence, by the time $t,$ all workers will have processed at least
    \begin{align*}
        \sum_{i=1}^{n} \flr{\frac{t}{2 \tau_i}}
    \end{align*}
    pairs. Assume that
    \begin{align*}
        j^* = \arg\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S + j)}.
    \end{align*}
    Using Lemma~\ref{lemma:techn1}, we have $t \geq 4 \tau_i$ for all $i \leq j^*.$ Thus, we get $\frac{t}{2 \tau_i} \geq 1$ for all $i \leq j^*$ and 
    \begin{align*}
        &\sum_{i=1}^{n} \flr{\frac{t}{2 \tau_i}} \geq \sum_{i=1}^{j^*} \flr{\frac{t}{2 \tau_i}} \geq \sum_{i=1}^{j^*} \frac{t}{4 \tau_i} \\
        &= \frac{1}{4} \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) \left(4 \parens{\sum_{i=1}^{j^*} \frac{1}{\tau_i}}^{-1} (S + j^*)\right) = S + j^* \geq S.
    \end{align*}
    We can conclude that by the time \eqref{eq:bath_diff_time}, the algorithm will have calculated $S$ pairs of stochastic gradients and exited the loop.
\end{proof}

\begin{theorem}\label{thm:batch}
    The time needed by Algorithm~\ref{algorithm:ga_asynch_batch} to calculate $g$ is at most
    \begin{align}
        2 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S + j)}
    \end{align}
    seconds.
\end{theorem}

\begin{proof}
    The proof of this theorem is essentially the same as the proof of Theorem~\ref{thm:bath_diff}. The only difference is that Algorithm~\ref{algorithm:ga_asynch_batch} calculates $\nabla f_i(x)$ instead of $\nabla f_i(x) - \nabla f_i(y).$
\end{proof}

\section{The Time Complexity Guarantees of Algorithms~\ref{algorithm:ga_asynch_main_new} and \ref{algorithm:ga_asynch_main_new_full}}
\label{sec:time_compl_sampling}

Instead of Algorithm~\ref{algorithm:ga_asynch_main_new}, we analyze a more general Algorithm~\ref{algorithm:ga_asynch_main_new_full} that reduces to Algorithm~\ref{algorithm:ga_asynch_main_new} when $\cS = [m].$

\begin{algorithm}[H]
    \centering
    \caption{\algname{ComputeBatchAnySampling}($\cS$, $x$)}
    \label{algorithm:ga_asynch_main_new_full}
    \begin{algorithmic}[1]
    \State \textbf{Input:} multiset $\cS$, point $x\in\R^d$
    \State Init $g=0\in\R^d$, multiset $\cM = \emptyset$
    \State Broadcast $x$ to all workers
    \State For each worker, sample $j$ from $\cS$ (uniformly) and ask it to calculate $\nabla f_j(x)$ \label{line:sample_one}
        \While{$\cM \neq \cS$}
            \State Wait for $\nabla f_p(x)$ from a worker
            \If{$p \in \cS \backslash \cM$}
            \State $g \gets g + \frac{1}{\abs{\cS}} \nabla f_p(x)$
            \State Update $\cM \gets \cM \cup \{p\}$
            \EndIf
            \State Sample $j$ from $\cS \backslash \cM$ (uniformly) \label{line:sample_two}
            and ask this worker to calculate $\nabla f_{j}(x)$
        \EndWhile
        \State Return $g = \frac{1}{\abs{\cS}} \sum\limits_{i \in \cS} \nabla f_i(x)$
    \end{algorithmic}
\end{algorithm}

\begin{restatable}{theorem}{THMFULLGRADTIMEFULL}
    \label{thm:compute_batch}
    The expected time needed by Algorithm~\ref{algorithm:ga_asynch_main_new_full} to calculate $g = \frac{1}{\abs{\cS}} \sum\limits_{i \in \cS} \nabla f_i$ is at most
    \begin{align}
        \label{eq:COVSRDFTGtaGOfFWmaO}
        12 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (\abs{\cS} + \min\{\abs{\cS},n\} \log \left(\min\{\abs{\cS},n\}\right) + j)}
    \end{align}
    seconds. 
\end{restatable}

\textit{Proof Sketch:} While the following proof is technical, the intuition and idea behind it and the algorithm are relatively simple. For simplicity, assume that $n \geq \abs{\cS}.$ The set $\cS \backslash \cM$ includes all indices that have not yet been calculated. Each worker is assigned a new random index from $\cS \backslash \cM$ and starts the calculation of the gradient. At the beginning of the algorithm, when the set $\cS \backslash \cM$ is large, the probability that two workers are assigned the same index is very small. Hence, using the same idea as in the proof of Theorem~\ref{thm:bath_diff}, the workers will calculate $\approx \abs{\cS} - n$ stochastic gradients after 
\begin{align*}
    \approx \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (\abs{\cS} - n + j)}
\end{align*}
seconds. However, once the size of $\cS \backslash \cM$ becomes roughly equal to $n$, the probability that two workers sample the same index increases. In the final steps of the algorithm, we encounter the same issue as in the famous \emph{coupon collector's problem}, resulting in an additional factor of $n \log n$ because some stochastic gradients will be calculated multiple times.

\begin{proof}
    Let us define $S = \abs{\cS}$ and take any $k \in [n].$ We refer to the workers with the upper bounds $\tau_i$ such that $\tau_i \leq \tau_{k}$ as ``fast'', and the others will be termed ``slow''. 


    Consider the moment when the algorithm samples $j$ from the set $\cS \backslash \cM$ to allocate it to one of the ``fast'' workers (\begin{NoHyper}Line~\ref{line:sample_one} or \ref{line:sample_two}\end{NoHyper}).
    The probability of sampling $j$ such that $\nabla f_j(x)$ is currently being calculated by another ``fast'' worker is
    \begin{align*}
        &\frac{\abs{\{\textnormal{indices from $\cS \backslash \cM$ taken by ``fast'' workers}\}}}{\abs{\{\textnormal{indices from $\cS \backslash \cM$ taken by ``fast'' workers}\}} + \abs{\{\textnormal{indices from $\cS \backslash \cM$ not taken by ``fast'' workers}\}}} \\
        &\leq \frac{\min\{k, S\}}{\min\{k, S\} + \abs{\{\textnormal{indices from $\cS \backslash \cM$ not taken by ``fast'' workers}\}}}
    \end{align*}
    because there are at most $k$ ``fast'' workers and at most $S$ distinct stochastic gradients. Let us define the set
    \begin{align*}
        \cU \eqdef \{\textnormal{indices from $\cS \backslash \cM$ not taken by ``fast'' workers}\}.
    \end{align*}
    A ``fast'' worker can be ``unlucky'' and start calculating a stochastic gradient that is being computed by another ``fast'' worker.
    However, with probability at least
    \begin{align*}
        \geq \frac{\abs{\cU}}{\min\{k, S\} + \abs{\cU}},
    \end{align*}
    it will take a new index $j$ that was not previously taken by another ``fast'' worker.


    Thus, the while loop of the algorithm defines a Markov process that begins with some $\cU \subseteq \cS.$ The size of $\cU$ decreases by one with probability at least $\frac{\abs{\cU}}{\min\{k, S\} + \abs{\cU}}$ in iterations where the algorithm samples $j$ from $\cU$ and asks a ``fast'' worker to calculate the stochastic gradient. Additionally, the size of $\cU$ can decrease by one when a ``slow'' worker finishes calculating a stochastic gradient from $\cU$.

    Let $\bar{t}$ be the time required for the Markov process to reach the state $\cU = \emptyset.$ Then, the while loop in Algorithm~\ref{algorithm:ga_asynch_main_new} will finish after at most 
    \begin{align}
    \label{eq:ItxNEbvoIPCNKKusLH}
    \bar{T} \eqdef \bar{t} + \tau_{k}
    \end{align} 
    seconds because once $\cU = \emptyset,$ all non-processed indices from $\cS \backslash \cM$ are assigned to the ``fast'' workers, so calculating the remaining stochastic gradients will take at most $\tau_{k}$ seconds.

    It remains to estimate $\bar{t}.$ Let $\eta_p$ be the number of iterations of the while loop where the algorithm samples $j$ from $\cS \backslash \cM$ and asks a ``fast'' worker to calculate the stochastic gradient when $\abs{\cU} = p.$ By the definition of the Markov chain, we have
    \begin{align}
        \label{eq:hzHdbQumZOGv}
        \Exp{\eta_p} \leq \left(\frac{p}{\min\{k, S\} + p}\right)^{-1} = 1 + \frac{\min\{k, S\}}{p}
    \end{align}
    because with probability at least $\frac{p}{\min\{k, S\} + p},$ one of the (``lucky'') ``fast'' workers receives $j$ from $\cU$ and decreases the size of $\cU$ by $1$ ($\eta_p$ has a geometric-like distribution).

    Since $\abs{\cU} \leq S$ at the beginning of the while loop, it is sufficient for the ``fast'' workers to calculate at most 
    \begin{align*}
        \sum_{p=1}^{S} \left(\eta_p + 1\right)
    \end{align*}
    stochastic gradients to ensure that $\cU = \emptyset$ (it is possible that some stochastic gradients will be calculated many times). Indeed, if $\abs{\cU} = p$ for the first moment, then after $\eta_p + 1$ calculations of stochastic gradients by the ``fast'' workers, the size of set will be at most $p - 1.$ The last ``plus one'' calculation can only happen when $\abs{\cU} = p - 1.$

    The time required for the ``fast'' workers to process this number of stochastic gradients is at most
    \begin{align*}
        t' = 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(\sum_{p=1}^{S} (\eta_p + 1)\right) + \tau_{k},
    \end{align*}
    because for this choice of $t'$, we have
    \begin{align*}
        \sum_{i=1}^{k} \flr{\frac{t'}{\tau_i}} \geq \frac{1}{2} \sum_{i=1}^{k} \frac{t'}{\tau_i} \geq \sum_{p=1}^{S} (\eta_p + 1),
    \end{align*}
    where $\flr{\frac{t'}{\tau_i}}$ is the number of stochastic gradients that worker $i$ can calculate in $t'$ seconds.
    Taking expectation gives
    \begin{align*}
        \Exp{t'}
        &= 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(\sum_{p=1}^{S} \Exp{\eta_p + 1}\right) + \tau_{k} \\
        &\overset{\eqref{eq:hzHdbQumZOGv}}{\leq} 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(2 S + \sum_{p=1}^{S} \frac{\min\{k, S\}}{p} \right) + \tau_{k} \\
        &\leq 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(2 S + \sum_{p=1}^{S} \frac{\min\{n, S\}}{p} \right) + \tau_{k} \\
        &= 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(2 S + \sum_{p=\min\{n, S\} + 1}^{S} \frac{\min\{n, S\}}{p} + \min\{n, S\} \sum_{p=1}^{\min\{n, S\}} \frac{1}{p} \right) + \tau_{k} \\
        &\leq 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(3 S + \min\{n, S\} \sum_{p=1}^{\min\{n, S\}} \frac{1}{p}\right) + \tau_{k} \\
        &\leq 2 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(3 S + \min\{n, S\} \left(2 + \log\left(\min\{n, S\}\right)\right)\right) + \tau_{k} \\
        &\leq 10 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(S + \min\{n, S\} \log\left(\min\{n, S\}\right)\right) + \tau_{k},
    \end{align*}
    where we use the standard bound on the harmonic series. Thus, the expectation of the total time \eqref{eq:ItxNEbvoIPCNKKusLH} can be bounded by
    \begin{align*}
        \Exp{\bar{T}} 
        &\leq 10 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(S + \min\{n, S\} \log\left(\min\{n, S\}\right)\right) + 2 \tau_{k} \\
        &\leq 10 \parens{\sum_{i=1}^{k} \frac{1}{\tau_i}}^{-1} \left(S + \min\{n, S\} \log\left(\min\{n, S\}\right) + k\right) + 2 \tau_{k},
    \end{align*}
    where in the last line we add $k \geq 0.$
    Recall that $k$ is a parameter we can choose. Let us take
    \begin{align*}
        k = \arg\min_{j\in[n]} \parens{\sum_{i=1}^{j} \frac{1}{\tau_i}}^{-1} \left(S + \min\{n, S\} \log\left(\min\{n, S\}\right) + j\right).
    \end{align*}
    Using Lemma~\ref{lemma:techn1}, we have
    \begin{align*}
        \tau_{k} \leq \min_{j \in [n]}\parens{\sum_{i=1}^{j} \frac{1}{\tau_i}}^{-1} \left(S + \min\{n, S\} \log\left(\min\{n, S\}\right) + j\right)
    \end{align*}
    and hence
    \begin{align*}
        \Exp{\bar{T}} 
        \leq 12 \min_{j \in [n]} \left(\parens{\sum_{i=1}^{j} \frac{1}{\tau_i}}^{-1} \left(S + \min\{n, S\} \log\left(\min\{n, S\}\right) + j\right)\right).
    \end{align*}









\end{proof}







































