\section{Proofs for Algorithm \ref{algorithm:rennala_page_gen} (\algnamelarge{Freya PAGE})}\label{sec:proofs_rennala_page}

The proofs use the simplified notation $\Teq(S) \eqdef \Teq(S, [\tau_i]_{i=1}^n)$ from Definition~\ref{def:time_budget}.


Since the update rule of \algname{PAGE} coincides with that of \algname{Freya PAGE}, one can directly apply the iteration complexity results established in \citet{tyurin2022sharper}.

\THMPAGERENNALAINDEPITER*

\begin{proof}
    The result follows from Theorem 6 of \citet{tyurin2022sharper}, using the parameters from the ``Uniform With Replacement'' line in Table 1 of the same work.
\end{proof}

\THMPAGERENNALATIME*
\begin{proof}
    The result established in Theorem \ref{thm:page_rate} says that the iteration complexity of the algorithm is
    \begin{align*}
        K_{\algname{PAGE}} \eqdef \frac{2 \delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{1-p}{pS}}}.
    \end{align*}
    At each iteration, with probability $1-p$, the workers compute $S$ differences of stochastic gradients, which by Theorem~\ref{thm:bath_diff} takes
    \begin{align*}
        4 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)}
    \end{align*}
    seconds. Otherwise, they collect the full gradient, which can be done (Theorem \ref{thm:full_grad_time}) in 
    \begin{align*}
        &12 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (m + \min\{m,n\} \log \left(\min\{m,n\}\right) + j)} \\
        &\leq 24 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (m+j)}
    \end{align*}
    seconds, where the inequality uses Assumption~\ref{ass:m_is_large}.
    Hence, recalling the notation
    \begin{align*}
        \Teq(S) \eqdef \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)},
    \end{align*}
    the (expected) time complexity of the method is
    \begin{align*}
        T(p,S, [\tau_i]_{i=1}^n) &= 24 \Teq(m) + 24 K_{\algname{PAGE}} \times \parens{p \Teq(m) + (1-p) \Teq(S)},
    \end{align*}
    where the term $\Teq(m)$ corresponds to the preprocessing step, when the algorithm needs to calculate $g^0 = \nabla f(x^0) = \nicefrac{1}{m} \sum_{i=1}^m \nabla f_i(x^0)$.
\end{proof}

\begin{theorem}
    \label{thm:opt_p_indep}
    Up to a constant factor, the time complexity $T(p,S, [\tau_i]_{i=1}^n)$ from \eqref{eq:compl_p_S_indep} is at least 
    \begin{align}
        \label{eq:T_S_indep}
        \Teq(m) + \frac{\delta^0}{\varepsilon}  \min\left\{L_- \Teq(m), L_- \Teq(S) + L_{\pm} \sqrt{\frac{\Teq(m)\Teq(S)}{S}} \right\},
    \end{align}
    and attains this value with 
    \begin{align}\label{eq:optimal_p_indep}
        p^*(S) = \begin{cases}
            1, & L_- \Teq(m) \leq L_- \Teq(S) + L_{\pm} \sqrt{\frac{\Teq(m)\Teq(S)}{S}} \\
            \frac{\Teq(S)}{\Teq(m)}, & \textnormal{otherwise}.
        \end{cases}
    \end{align}
\end{theorem}

\begin{proof}
    Up to a constant factor, by Theorem \ref{thm:page_time_compl}, the time complexity of \algname{Freya PAGE} is
    \begin{align*}
        T(p,S, [\tau_i]_{i=1}^n) \eqdef \Teq(m) + \frac{\delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{1-p}{p S}}} 
        \parens{p \Teq(m) + (1-p) \Teq(S)}.
    \end{align*}
    Let us denote the second term in the above equation as $T_{p,S}$. Then for all $p \geq \frac{1}{2},$ we have
    \begin{align}\label{eq:tpropto_indep}
        T_{p,S} 
        &\propto \frac{\delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{1-p}{pS}}} \parens{p \Teq(m) + (1-p) \Teq(S)}
        \geq \frac{\delta^0}{2\varepsilon} L_- \Teq(m),
    \end{align}
    and for all $S \geq \frac{m}{2}$
    \begin{align*}
        T_{p,S} 
        &\geq \frac{\delta^0}{\varepsilon} L_- \brac{p \Teq(m)
        + (1-p) \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{m}{2}+j}}}
        \geq \frac{\delta^0}{2 \varepsilon} L_- \Teq(m).
    \end{align*}
    Otherwise, when $p < \frac{1}{2}$ and $S < \frac{m}{2}$, we have
    \begin{align*}
        T_{p,S} 
        &\geq \frac{\delta^0}{2 \varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{1}{p S}}} \parens{p \Teq(m) + \Teq(S)} \\
        &\geq \frac{\delta^0}{2 \varepsilon} L_- \Teq(S) + \frac{\delta^0}{2 \varepsilon} \parens{L_{\pm} \sqrt{\frac{1}{p S}}} \parens{p \Teq(m) + \Teq(S)} \\
        &\geq \frac{\delta^0}{2 \varepsilon} L_- \Teq(S) + \frac{\delta^0}{\varepsilon} \parens{L_{\pm} \sqrt{\frac{1}{p S}}} \sqrt{p \Teq(m)\Teq(S)} \\
        &= \frac{\delta^0}{2 \varepsilon} L_- \Teq(S) + \frac{\delta^0}{\varepsilon} L_{\pm} \sqrt{\frac{\Teq(m)\Teq(S)}{S}}.
    \end{align*}
    Hence, up to a constant factor,
    \begin{align*}
        T(p,S, [\tau_i]_{i=1}^n)
        = \Teq(m) + T_{p,S}
        \geq \Teq(m) + \frac{\delta^0}{\varepsilon}  \min\left\{L_- \Teq(m), L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}} \right\}.
    \end{align*}
    It can be easily verified that this bound can be attained (up to a constant factor) using the parameter $p$ as defined in~\eqref{eq:optimal_p_indep}.
\end{proof}

\begin{theorem}\label{thm:opt_S}
    Up to a constant factor, the minimum of the time complexities \eqref{eq:compl_p_S_indep} and \eqref{eq:T_S_indep} is
    \begin{align*}
        \Teq(m) + \frac{\delta^0}{\varepsilon}  \min\left\{L_- \Teq(m), \min_{S \in [m]} \left[L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}\right] \right\}
    \end{align*}
    and is achieved for 
    \begin{align*}
        S^* = \arg\min_{S \in [m]} \min\left\{L_- \Teq(m), L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}} \right\}
    \end{align*}
    and $p^* = p^*(S^*),$ where $p^*(S)$ is defined in \eqref{eq:optimal_p_indep}.
\end{theorem}
\begin{proof}
    This is a simple corollary of Theorem~\ref{thm:opt_p_indep}: we take $S$ that minimizes \eqref{eq:T_S_indep}.
\end{proof}

In certain scenarios, we can derive the optimal parameter values explicitly.

\begin{theorem}\label{thm:rpage_psopt_indep}
    \leavevmode
    \begin{enumerate}
        \item If $n \leq \frac{L_{\pm} \sqrt{m}}{L_-} \leq m$, then (up to constants) $S^* = \frac{L_{\pm} \sqrt{m}}{L_-}$ and $p^* = \frac{L_{\pm}}{L_- \sqrt{m}}$ are optimal parameters and
        \begin{align*}
            T(p^*,S^*,[\tau_i]_{i=1}^n) = \Teq(m) + \frac{\delta^0 L_-}{\varepsilon}
            \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}.
        \end{align*}
        \item If $\frac{L_{\pm}\sqrt{m}}{L_-} \leq 1$, then (up to constants) $S^* = 1$ and $p^* = \nicefrac{1}{m}$ are optimal parameters and
        \begin{align*}
