        \end{align*}
        \item If $\frac{L_{\pm}\sqrt{m}}{L_-} \geq m$, then (up to constants) $p^* = 1$ is an optimal parameter and
        \begin{align*}
            T(p^*,S,[\tau_i]_{i=1}^n) = \frac{\delta^0 L_-}{\varepsilon} \Teq(m)
        \end{align*}
        for any $S\in[m]$.
    \end{enumerate}
\end{theorem}

\begin{proof}
    We fist consider the case when $n \leq \frac{L_{\pm} \sqrt{m}}{L_-} \leq m$.
    Since $j \leq n \leq \frac{L_{\pm} \sqrt{m}}{L_-}$, we have
    \begin{align}\label{eq:ineq1tm_indep}
        \frac{L_{\pm} \sqrt{m}}{L_-} + \frac{L_{\pm}}{L_- \sqrt{m}} j \geq \frac{1}{2} \left(\frac{L_{\pm} \sqrt{m}}{L_-} + j\right),
    \end{align}
    and from the assumption that $L_- \geq \frac{L_{\pm}}{\sqrt{m}}$ it follows that
    \begin{align}\label{eq:ineq2tm_indep}
        \frac{L_{\pm} \sqrt{m}}{L_-} + j \geq \frac{L_{\pm} \sqrt{m}}{L_-} + \frac{L_{\pm}}{L_- \sqrt{m}} j
    \end{align}
    for all $j \in [n]$. Thus,
    \begin{align*}
        \frac{L_{\pm}}{L_-\sqrt{m}} \Teq(m)
        = \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\pm} \sqrt{m}}{L_-} + \frac{L_{\pm}}{L_-\sqrt{m}} j}}
        \overset{\eqref{eq:ineq1tm_indep}}{\geq} \frac{1}{2} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}},
    \end{align*}
    and
    \begin{align*}
        \frac{L_{\pm}}{L_-\sqrt{m}} \Teq(m)
        = \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\pm} \sqrt{m}}{L_-} + \frac{L_{\pm}}{L_-\sqrt{m}} j}}
        \overset{\eqref{eq:ineq2tm_indep}}{\leq} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}.
    \end{align*}
    It follows that
    \begin{align}
        \label{eq:ineq3tmt_indep}
        \frac{1}{2} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}} \leq \frac{L_{\pm}}{L_-\sqrt{m}} \Teq(m) \leq \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}.
    \end{align}
    Since $\frac{L_{\pm} \sqrt{m}}{L_-} \leq m$,  we have
    \begin{align}\label{eq:toptin_indep}
        \min_{S \in [m]} \left\{L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}\right\}
        &\leq L_- \min_{S \in [m]} \left\{\Teq(S) + \sqrt{m} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}\right\} \nonumber \\
        &\leq 2 L_- \Teq(m),
    \end{align}
    and thus, according to the result from Theorem \ref{thm:opt_S}, it is sufficient to minimize
    \begin{align*}
        t'(S) \eqdef L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}.
    \end{align*}
    First, let us note that
    \begin{align*}
        t'\parens{\frac{L_{\pm} \sqrt{m}}{L_-}} %&= L_- \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}} + L_{\pm} \sqrt{\frac{\Teq(m) \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}}{\frac{L_{\pm} \sqrt{m}}{L_-}}} \\
        &= L_- \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}
        + L_{\pm} \sqrt{\frac{L_-}{L_{\pm} \sqrt{m}} \Teq(m) \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}} \\
        &\overset{\eqref{eq:ineq3tmt_indep}}{\leq} L_- \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}
        + L_{\pm} \sqrt{\frac{L_-}{L_{\pm} \sqrt{m}} \frac{L_-\sqrt{m}}{L_{\pm}} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}} \\
        &= 2 L_- \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}.
    \end{align*}
    If $S \geq \frac{L_{\pm} \sqrt{m}}{L_-}$, then
    \begin{align*}
        t'(S) = L_- \Teq(S) + L_{\pm} \sqrt{\frac{\Teq(m)\Teq(S)}{S}} \geq L_- \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}.
    \end{align*}
    Otherwise, if $S < \frac{L_{\pm} \sqrt{m}}{L_-}$, then
    \begin{align*}
        t'(S) &= L_- \Teq(S) + L_{\pm} \sqrt{\Teq(m)} \sqrt{\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{1+ \frac{j}{S}}}} \\
        &\geq L_{\pm} \sqrt{\Teq(m)} \sqrt{\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{1+ \frac{L_- j}{L_{\pm} \sqrt{m}}}}} \\
        &= L_{\pm} \sqrt{\Teq(m)} \sqrt{\frac{L_-}{L_{\pm} \sqrt{m}} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\pm} \sqrt{m}}{L_-} + j}}} \\
        &= L_{\pm} \sqrt{\Teq(m) \frac{L_-}{L_{\pm} \sqrt{m}} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}} \\
        &\overset{\eqref{eq:ineq3tmt_indep}}{\geq} L_{\pm} \sqrt{\frac{1}{2} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}} \frac{L_-\sqrt{m}}{L_{\pm}} \frac{L_-}{L_{\pm} \sqrt{m}} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}} \\
        &= \frac{L_-}{\sqrt{2}} \Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}.
    \end{align*}
    Therefore, the optimal choice is $S^* = \frac{L_{\pm} \sqrt{m}}{L_-}$, and by Theorem \ref{thm:opt_p_indep} and inequality \eqref{eq:toptin_indep}, $p$ should chosen to be
    \begin{align*}
        \frac{\Teq\parens{\frac{L_{\pm} \sqrt{m}}{L_-}}}{\Teq(m)}.
    \end{align*}
    Using \eqref{eq:ineq3tmt_indep}, we can conclude that $p^* = \frac{L_{\pm}}{L_- \sqrt{m}}$ is optimal, proving the first part of the Theorem.

    Next, consider the case when $\frac{L_{\pm}\sqrt{m}}{L_-} \leq 1$.
    By the reasoning above, it is sufficient to minimize
    \begin{align*}
        t'(S) \eqdef L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}.
    \end{align*}
    First, let us note that
    \begin{align*}
        t'(1) &= L_- \Teq(1) + L_{\pm} \sqrt{\Teq(m)\Teq(1)}
        \leq L_- \Teq(1) + L_- \sqrt{\frac{\Teq(m)\Teq(1)}{m}}
        \leq 2 L_- \Teq(1),
    \end{align*}
    where the last inequality follows from the fact that for any $S\in[m]$, $\nicefrac{\Teq(S)}{S} \leq \Teq(1)$.
    On the other hand, if $S \geq 1$, then
    \begin{align*}
        t'(S) = L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}
        \geq L_- \Teq(S)
        \geq L_- \Teq(1).
    \end{align*}
    Therefore, the optimal choice is $S^* = 1$. Then
    \begin{align*}
        &\frac{\delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{m-1}} \parens{\frac{\Teq(m)}{m} + \parens{1-\frac{1}{m}} \Teq(1)} \\
        &\leq \frac{2\delta^0}{\varepsilon} \parens{L_- + \frac{L_-}{\sqrt{m}} \sqrt{m-1}} \Teq(1) \\
        &\leq \frac{4\delta^0 L_-}{\varepsilon} \Teq(1),
    \end{align*}
    while for any $p$
    \begin{align*}
        &\frac{\delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{1-p}{p}}} \parens{p \Teq(m) + (1-p) \Teq(1)} \\
        &\geq \frac{\delta^0 L_-}{\varepsilon} \parens{p \Teq(m) + (1-p) \Teq(1)} \\
        &\geq \frac{\delta^0 L_-}{\varepsilon} \parens{p \Teq(1) + (1-p) \Teq(1)} \\
        &= \frac{\delta^0 L_-}{\varepsilon} \Teq(1).
    \end{align*}
    Hence $p^*=\nicefrac{1}{m}$.

    It remains to prove the third result. Suppose that $L_- < \frac{L_{\pm}}{\sqrt{m}}$. Then, the last part of the theorem follows from the fact that
    \begin{align*}
        \min_{S \in [m]} \left\{L_- \Teq(S) + L_{\pm} \frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}\right\} &\geq L_{\pm} \min_{S \in [m]} \left\{\frac{\sqrt{\Teq(m)\Teq(S)}}{\sqrt{S}}\right\} \\
        &= L_{\pm} \left\{\frac{\sqrt{\Teq(m)\Teq(m)}}{\sqrt{m}}\right\} \\
        &\geq L_- \Teq(m).
    \end{align*}
\end{proof}

In practice, the values of smoothness constants are often unknown. However, the algorithm can still be run with close to optimal parameters. 

\THEOREMSIMPLETIMECOMPLEXITYCHOICE*

\begin{proof}
    The proof is the same as in Theorem~\ref{thm:rpage_psopt_indep}. Indeed, 
    up to a constant factor, the time complexity~\eqref{eq:compl_p_S_indep} can be bounded as
    \begin{align*}
        T(p,S, [\tau_i]_{i=1}^n) &=  \Teq(m) + \frac{\delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{1-p}{pS}}} \parens{p \Teq(m) + (1-p) \Teq(S)} \\
        &\leq  \Teq(m) + \frac{2 \delta^0 \max\{L_-,L_{\pm}\}}{\varepsilon} \parens{1 + \sqrt{\frac{1-p}{pS}}} \parens{p \Teq(m) + (1-p) \Teq(S)}.
    \end{align*}
    Therefore, by setting $L_{\pm} = L_-$ in Theorem \ref{thm:rpage_psopt_indep}, one can easily derive the parameters $p$ and $S$ that are optimal up to the smoothness constants. The time complexity \eqref{eq:time_comp} can be obtained by applying $S = \ceil{\sqrt{m}}$ and $p = \nicefrac{1}{\sqrt{m}}$ to \eqref{eq:compl_p_S_indep}.
\end{proof}

