\section{\algnamelarge{Freya PAGE} with Other Samplings}\label{sec:proofs_rennala_page_other}

Algorithm~\ref{algorithm:rennala_page_gen} can be adapted to accommodate other sampling methods. This brings us to the introduction of Algorithm~\ref{algorithm:rennala_page_gen_any}, which supports virtually any sampling strategy, formalized by the following mapping:

\begin{definition}[Sampling]\label{def:sampling}
    A \emph{sampling} is a random mapping $\mS_S$, which takes as an input a set of indices $\cI \eqdef \{a_1,\ldots,a_m\}$ and returns a (multi)set $\{a_{i_1}, \ldots, a_{i_S}\}$, where $a_{i_j} \in \cI$ for all $j\in[S]$.
\end{definition}

\begin{algorithm}[H]
    \caption{\algname{Freya PAGE} (with virtually any sampling)}
    \label{algorithm:rennala_page_gen_any}
    \begin{algorithmic}[1]
    \State \textbf{Parameters:} starting point $x^0 \in \R^d$, learning rate $\gamma > 0$, minibatch size $S$, sampling $\mS_S$, probability $p \in (0, 1]$, initialization $g^0 = \nabla f(x^0)$ using ${\green \textnormal{\algname{ComputeGradient}}([m], x^{0})}$ \quad (Alg.~\ref{algorithm:ga_asynch_main_new})
    \For{$k = 0, 1, \ldots, K-1$}
        \State $x^{k+1} = x^k - \gamma g^k$
        \State Sample $c^k \sim \text{Bernoulli}(p)$
        \If{$c^k=1$}
            \State {\green $\nabla f(x^{k+1}) = \textnormal{\algname{ComputeGradient}}(x^{k+1})$} \hfill (Alg.~\ref{algorithm:ga_asynch_main_new})
            \State $g^{k+1} = \nabla f(x^{k+1})$
        \Else
            \State Sample indices $\cS^k = \mS_S([m])$
            \State {\green $\frac{1}{S} \sum\limits_{i \in \cS^k}\left(\nabla f_i(x^{k+1}) - \nabla f_i(x^{k})\right)$} \newline \hspace*{1cm} {\green $= \textnormal{\algname{ComputeBatchDifferenceAnySampling}}(\cS^k, x^{k+1}, x^k)$} \hfill (Alg.~\ref{algorithm:ga_asynch_main_new_full_diff})
            \State $g^{k+1} = g^k + \frac{1}{S} \sum\limits_{i \in \cS^k}\left(\nabla f_i(x^{k+1}) - \nabla f_i(x^{k})\right)$ 
        \EndIf
    \EndFor
    \end{algorithmic}
\end{algorithm}

\begin{algorithm}[H]
    \centering
    \caption{\algname{ComputeBatchDifferenceAnySampling}($\cS$, $x$, $y$)}
    \label{algorithm:ga_asynch_main_new_full_diff}
    \begin{algorithmic}[1]
    \State \textbf{Input:} multiset $\cS$, points $x,y\in \R^d$
    \State Init $g=0\in \R^d$, multiset $\cM = \emptyset$
    \State Broadcast $x$ to all workers
    \State For each worker, sample $j$ from $\cS$ (uniformly) and ask it to calculate $\nabla f_j(x) - \nabla f_j(y)$
        \While{$\cM \neq \cS$}
            \State Wait for $\nabla f_p(x) - \nabla f_p(y)$ from a worker
            \If{$p \in \cS \backslash \cM$}
            \State $g \gets g + \frac{1}{\abs{\cS}} \left(\nabla f_p(x) - \nabla f_p(y)\right)$
            \State Update $\cM \gets \cM \cup \{p\}$
            \EndIf
            \State Sample $j$ from $\cS \backslash \cM$ (uniformly)
            and ask this worker to calculate $\nabla f_{j}(x) - \nabla f_{j}(y)$
        \EndWhile
        \State Return $g = \frac{1}{\abs{\cS}} \sum\limits_{i \in \cS} \left(\nabla f_i(x) - \nabla f_i(y)\right)$
    \end{algorithmic}
\end{algorithm}

The only difference is that instead of \algname{ComputeBatchDifference} (Algorithm~\ref{algorithm:ga_asynch_main_new_full}), Algorithm~\ref{algorithm:rennala_page_gen_any} uses a new subroutine, called \algname{ComputeBatchDifferenceAnySampling} (Algorithm~\ref{algorithm:ga_asynch_main_diff}). 

For this algorithm, we can prove the following time complexity guarantees.

\begin{restatable}{theorem}{THMFULLGRADTIMEFULLGENERIC}
    \label{thm:calculate_gradient_diff}
    The expected time needed by Algorithm~\ref{algorithm:ga_asynch_main_new_full_diff} to calculate $g = \frac{1}{\abs{\cS}} \sum\limits_{i \in \cS} (\nabla f_i(x) - \nabla f_i(y))$ is at most
    \begin{align}
        24 \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (\abs{\cS} + \min\{\abs{\cS},n\} \log \left(\min\{\abs{\cS},n\}\right) + j)}
    \end{align}
    seconds. 
\end{restatable}

\begin{proof}
    The proof of this theorem is the same as the proof of Theorem~\ref{thm:compute_batch}. We only have to multiply~\eqref{eq:COVSRDFTGtaGOfFWmaO} by $2$ because Algorithm~\ref{algorithm:ga_asynch_main_diff} calculates $\nabla f_i(x) - \nabla f_i(y)$ instead of $\nabla f_i(x).$
\end{proof}

While changing the sampling strategy might affect the \emph{iteration complexity} of the method, for a fixed minibatch size $S$, the \emph{time complexity of a single iteration} remains unchanged. Thus, having established the expected time needed by the algorithm to perform a single iteration (i.e., to collect a minibatch of stochastic gradients of the required size), one can simply multiply it by the iteration complexity of the method determined for any supported sampling technique to obtain the resulting time complexity.

With this in mind, we now analyse the time complexity of Algorithm~\ref{algorithm:rennala_page_gen_any} with $2$ different sampling techniques: nice sampling and importance sampling. However, it can be analyzed with virtually any other unbiased sampling \citep{tyurin2022sharper}.

\subsection{Nice sampling}
\label{sec:nice}

\emph{Nice sampling} returns a random subset of fixed cardinality $S$ chosen uniformly from $[m]$. Unlike \emph{uniform sampling with replacement} used in Algorithm~\ref{algorithm:ga_asynch_main_new_full}, which returns a random multiset (that can include repetitions), the samples obtained by nice sampling are distinct. The iteration complexity of Algorithm~\ref{algorithm:rennala_page_gen_any} with nice sampling is given by the following theorem.

\begin{theorem}[\citet{tyurin2022sharper}, Section $3$]\label{thm:page_iter_nice}
    Let Assumptions \ref{as:smooth_lower_bdd}, \ref{as:L+} and \ref{as:L_pm} hold. Choose a minibatch size $S\in[m]$, a probability $p \in (0, 1]$ and the stepsize
    \begin{align*}
        \gamma = \frac{1}{L_- + L_{\pm} \sqrt{\frac{(1-p)(m-S)}{p(m-1)S}}}.
    \end{align*}
    Then, the number of iteration needed by Algorithm~\ref{algorithm:rennala_page_gen_any} with \emph{nice sampling} to reach an $\varepsilon$-stationary point is
    \begin{align}\label{eq:page_iter_nice}
        K = \frac{2 \delta^0}{\varepsilon} \left(L_- + L_{\pm} \sqrt{\frac{(1-p)(m-S)}{p(m-1)S}}\right).
    \end{align}
\end{theorem}
\begin{proof}
    The result follows from Theorem $6$ and Table 1 from \citep{tyurin2022sharper}.
\end{proof}

\begin{theorem}\label{thm:page_time_compl_nice}
    Consider the assumptions and parameters from Theorem~\ref{thm:page_iter_nice} and Assumption~\ref{ass:m_is_large}. Up to a constant factor, the time complexity of Algorithm~\ref{algorithm:rennala_page_gen_any} is
    \begin{align}\label{eq:compl_p_S_nice}
        &T(p,S, [\tau_i]_{i=1}^n) = \Teq(m, [\tau_i]_{i=1}^n)
        + \frac{\delta^0}{\varepsilon} \parens{L_- + L_{\pm} \sqrt{\frac{(1-p)(m-S)}{p(m-1)S}}} \times \nonumber \\
        &\times \brac{p \times \Teq(m, [\tau_i]_{i=1}^n) + (1-p)  \times \Teq(S + \min\{S,n\} \log \left(\min\{S,n\}\right), [\tau_i]_{i=1}^n)},
    \end{align}
    where $t^*$ is defined from Definition~\ref{def:time_budget}.
\end{theorem}

\begin{remark}
    Compared to Theorem~\ref{thm:page_time_compl}, which uses \emph{uniform sampling with replacement}, the guarantees for \emph{nice sampling} are slightly worse: the term $\Teq(S, [\tau_i]_{i=1}^n)$ from Theorem~\ref{thm:page_time_compl} here is replaced with $\Teq(S + \min\{S,n\} \log \left(\min\{S,n\}\right), [\tau_i]_{i=1}^n).$ Ignoring the logarithmic term $\log \left(\min\{S,n\}\right)$ ($\leq \log \left(\min\{m,n\}\right)$), the result from Theorem~\ref{thm:page_time_compl_nice} is equivalent to that in Theorem~\ref{thm:page_time_compl}. Thus, Theorems~\ref{thm:opt_S_main} and \ref{cor:nice_upper_bound} hold also for the nice sampling (up to logarithmic factors).
\end{remark}

\begin{proof}
    We use the same reasoning as in the proof of Theorem \ref{thm:page_time_compl}. With probability $p,$ the algorithm calculates the full gradients, which by Theorem~\ref{thm:full_grad_time} requires
    \begin{align*}
        &\Theta\left(\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (m + \min\{m,n\} \log \left(\min\{m,n\}\right) + j)}\right) \\
        &=\Theta\left(\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (m + j)}\right) \\
    \end{align*}
    seconds, where we use Assumption~\ref{ass:m_is_large}. With probability $1 - p,$ the algorithm calls \algname{ComputeBatchDifferenceAnySampling}, which by Theorem~\ref{thm:calculate_gradient_diff} requires
    \begin{align*}
        \Theta\left(\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S + \min\{S,n\} \log \left(\min\{S,n\}\right) + j)}\right)
    \end{align*}
    seconds. One can obtain the result by multiplying the iteration complexity \eqref{eq:page_iter_nice} by the expected time needed to collect the required number of stochastic gradients per iteration and adding the preprocessing time.
\end{proof}






\subsection{Importance sampling}
\label{sec:importance}

Here we additionally assume $L_i$-smoothness of the local objective functions $f_i$.

\begin{assumption}\label{as:worker_smooth}
    The functions $f_i$ are $L_i$-smooth. We denote $\bar{L} \eqdef \frac{1}{m} \sum_{j=1}^m L_j$ and $L_{\max} \eqdef \max_{i \in [n]} L_i.$
\end{assumption}

Importance sampling is a sampling technique that returns a multiset of indices \emph{with repetitions}. Index $j$ is included in the multiset with probability $\frac{L_j}{\sum_{i=1}^{n} L_j}.$

\begin{theorem}[\citet{tyurin2022sharper}, Section $3$]\label{thm:page_iter_import}
    Let Assumptions \ref{as:smooth_lower_bdd} and \ref{as:worker_smooth} hold. Choose a minibatch size $S\in[m]$, probability $p \in (0, 1]$ and the stepsize
    \begin{align*}
        \gamma = \frac{1}{L_- + \bar{L} \sqrt{\frac{1-p}{pS}}}.
    \end{align*}
    Then, the number of iteration needed by Algorithm~\ref{algorithm:rennala_page_gen} with \emph{importance sampling} to reach an $\varepsilon$-stationary point is
    \begin{align}\label{eq:iter_compl_import}
        K = \frac{2 \delta^0}{\varepsilon} \parens{L_- + \bar{L} \sqrt{\frac{1-p}{pS}}}.
    \end{align}
\end{theorem}

The complexity \eqref{eq:iter_compl_import} is nearly identical to \eqref{eq:iter_compl_indep} and \eqref{eq:page_iter_nice}, with the only difference being the dependence on $\bar{L}$ rather than $L_{\pm}$. Thus, all the results up to constant and logarithmic factors can be derived using the same methodology as that outlined in Section~\ref{sec:theory}, with the simple substitution of $L_{\pm}$ with $\bar{L}$. 





\section{Dynamic Bounds}

As noted in Section \ref{sec:time_var_times}, the results from Section \ref{sec:proofs_rennala_page} can be easily generalized to iteration-dependent processing times.

\begin{theorem}\label{thm:page_time_compl_var}
    Consider the assumptions and the parameters from Theorem~\ref{thm:page_rate} and Assumption~\ref{ass:m_is_large}. Up to a constant factor, the time complexity of \algname{Freya PAGE} (Algorithm~\ref{algorithm:rennala_page_gen}) with iteration-dependent processing times $\{\tau_i^k\},$ which are defined in Section~\ref{sec:time_var_times}, is at most
    {\small\begin{align}\label{eq:compl_p_S_var}
    &\min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_{\pi_{-1,i}}^{-1}}}^{-1} (m+j)}\nonumber \\
        &\qquad+ \sum_{k=0}^{\ceil{K_{\algname{PAGE}}}} \brac{p \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_{\pi_{k,i}}^k}}^{-1} (m+j)}
        + (1-p) \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_{\pi_{k,i}}^k}}^{-1} (S+j)}},
    \end{align}}
    to find an $\varepsilon$-stationary point, where $p \in (0, 1]$ and $S \in \N$ are free parameters, and $\pi_{k,\cdot}$ is a permutation such that $\tau_{\pi_{k,1}}^k \leq \dots \leq \tau_{\pi_{k,n}}^k$ for all $k \geq -1.$
\end{theorem}

\begin{remark}
    The theorem can be trivially extended to other samplings by changing $K_{\algname{PAGE}}$ to the iteration complexities from Theorems~\ref{thm:page_iter_nice} and \ref{thm:page_iter_import}.
\end{remark}

\begin{proof}
    The reasoning behind this result is exactly the same as in the proof of Theorem \ref{thm:page_time_compl}. The only difference is that in this more general setting, the expected time per iteration varies across iterations. Therefore, instead of simply multiplying, one needs to sum over the iterations to obtain the total time complexity. 

    We introduce the permutations to ensure that $\{\tau_{\pi_{k,i}}^k\}_{i=1}^n$ are sorted. When $\tau_{i}^k = \tau_{i},$ there is no need to introduce them because, throughout the paper, it is assumed $\tau_1\leq\ldots\leq\tau_n$ (see Section \ref{sec:intro}).
\end{proof}


