\section{Examples}\label{sec:examples_proofs}

Here we provide the proofs for the examples from Section \ref{sec:discussion}. We will use the notation
\begin{align*}
    t(S,j) \eqdef \parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)
\end{align*}
for a fixed $S\in[m]$ and all $j\in[n]$.

\EXAMPLESAMEMAIN*
\begin{proof}
    First, when $\tau_j=\tau$ for all $j\in[n]$, then for any $S\in[m]$, $t(S,j)$ is minimized by taking $j = n$:
    \begin{align*}
        \Teq(S) &\eqdef \min_{j\in[n]} t(S,j) = \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)} \\
        &= \min_{j\in[n]} \parens{\frac{\tau}{j} (S+j)}
        = \Theta\left(\tau \max\left\{\frac{S}{n}, 1\right\}\right).
    \end{align*}
    It remains to substitute this equality in \eqref{eq:time_comp}.



\end{proof}

\EXAMPLEINFFASTMAIN*
\begin{proof}
    The statement follows easily from the fact that for any $S\in[m]$ we have
    \begin{align*}
        \Teq(S) \eqdef \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)}
        \leq \parens{\frac{1}{\tau_1}}^{-1} (S+j)
        = 0.
    \end{align*}
\end{proof}

\EXAMPLEINFSLOWMAIN*
\begin{proof}
    This follows from the fact that for any $S\in[m]$ and any $j\in[n]$ we have
    \begin{align*}
        t(S,j) \eqdef \parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j) = \infty.
    \end{align*}
\end{proof}

\EXAMPLESLOWMAIN*
\begin{proof}
    Suppose that $B \geq \frac{m+j_B}{\sum_{i=1}^{j_B} \frac{1}{\tau_i}}$ and fix any $k>j_B$. Then, since $\tau_j\geq B$ for all $j > j_{B}$, we have
    \begin{align*}
        \frac{k-j_B}{\sum_{i=j_B+1}^{k} \frac{1}{\tau_i}}
        \geq \frac{k-j_B}{\sum_{i=j_B+1}^{k} \frac{1}{B}}
        = B
        \geq \frac{m+j_B}{\sum_{i=1}^{j_B} \frac{1}{\tau_i}}
        \geq \frac{S+j_B}{\sum_{i=1}^{j_B} \frac{1}{\tau_i}}
        = t(S,j_B)
    \end{align*}
    for any $S\in[m]$. Rearranging and adding $\parens{S+j_B} \sum_{i=1}^{j_B} \frac{1}{\tau_i}$ to both sides of the inequality, we obtain
    \begin{align*}
        \parens{S+j_B} \parens{\sum_{i=1}^{j_B} \frac{1}{\tau_i}} + \parens{S+j_B} \parens{\sum_{i=j_B+1}^{k} \frac{1}{\tau_i}} \leq \parens{S + j_B} \parens{\sum_{i=1}^{j_B} \frac{1}{\tau_i}} + \parens{k - j_B} \parens{\sum_{i=1}^{j_B} \frac{1}{\tau_i}},
    \end{align*}
    meaning that
    \begin{align*}
        t(S,j_B) = \frac{S+j_B}{\sum_{i=1}^{j_B} \frac{1}{\tau_i}} \leq \frac{S+k}{\sum_{i=1}^{k} \frac{1}{\tau_i}} = t(S,k)
    \end{align*}
    for any $k>j_B$ and any $S\in[m]$. Therefore,
    \begin{align*}
        \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)}
        = \min_{j\in[j_B]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)}
    \end{align*}
    for any $S\in[m]$, which proves the claim.
\end{proof}





























