\section{A New Stochastic Gradient Method: \algnamelarge{Freya SGD}}
\label{sec:freya_sgd}

In this section, we introduce a new a non-variance reduced \algname{SGD} method that we call \algname{Freya SGD}. \algname{Freya SGD} is closely aligned with \algname{Rennala SGD} \citep{tyurin2023optimal}, but \algname{Freya SGD} does not require the $\sigma^2$--bounded variance assumption on stochastic gradients.


\begin{algorithm}[H]
    \caption{\algname{Freya SGD}}
    \label{algorithm:rennala_sgd}
    \begin{algorithmic}[1]
    \State \textbf{Parameters:} starting point $x^0 \in \R^d$, learning rate $\gamma > 0$, minibatch size $S$
    \For{$k = 0, 1, \ldots, K-1$}
        \State {\green $\frac{1}{S} \sum\limits_{i \in \cS^k} \nabla f_i(x^{k}) = \textnormal{\algname{ComputeBatch}}(S, x^k)$} \hfill (Alg.~\ref{algorithm:ga_asynch_batch})
        \State $x^{k+1} = x^k - \gamma \frac{1}{S} \sum\limits_{i \in \cS^k} \nabla f_i(x^{k})$
    \EndFor
    \end{algorithmic}
    {\small \hspace*{0.5cm} (note): $\cS^k$ is a set of size $\abs{\cS^k} = S$} of i.i.d. indices sampled from $[m]$ \emph{uniformly with replacement}
\end{algorithm}


\begin{assumption}
    \label{ass:local_lower_bound}
    For all $i \in [n],$ there exists $f^*_i$ such that $f_i(x) \geq f^*_i$ for all $x \in \R^d.$
\end{assumption}
We define
\begin{align*}
    \Delta^* \eqdef \frac{1}{n} \sum_{i=1}^{n} \left(f^* - f^*_i\right).
\end{align*}

\begin{theorem}
    \label{thm:sgd}
    Let Assumptions \ref{as:smooth_lower_bdd}, \ref{as:worker_smooth} and \ref{ass:local_lower_bound} hold. Choose minibatch size $S\in[m]$ and stepsize
    \begin{align*}
        \gamma = \min\left\{\frac{\sqrt{S}}{\sqrt{L L_{\max} K_{\textnormal{SGD}}}}, \frac{1}{L \left(1 - \frac{1}{S}\right)}, \frac{S \varepsilon}{4 L L_{\max}\Delta^*}\right\},
    \end{align*}
    where
    \begin{align*}
        K_{\textnormal{SGD}} \eqdef \frac{12 \delta^0 L}{\varepsilon} \max \left\{1 - \frac{1}{S}, \frac{12 L_{\max} \delta^0}{S \varepsilon}, \frac{4 L_{\max}\Delta^*}{S \varepsilon}\right\}.
    \end{align*}
    Then, the number of iterations needed by Algorithm~\ref{algorithm:rennala_sgd} to reach an $\varepsilon$-stationary point is $\ceil{K_{\textnormal{SGD}}}.$
\end{theorem}

\begin{proof}
    The iteration complexity can be proved using Corollary~1 and Proposition~3 (i) of \citet{khaled2020better} (with $q_i = 1 / n$).
\end{proof}

\begin{theorem}\label{thm:rennala_sgd_indep}
    Consider the assumptions and the parameters from Theorem~\ref{thm:sgd}. Up to a constant factor, the time complexity of \algname{Freya SGD} (Algorithm~\ref{algorithm:rennala_sgd}) is at most
    \begin{align*}
        T_{\textnormal{SGD}}(S, [\tau_i]_{i=1}^n)  &\eqdef \frac{\delta^0 L_-}{\varepsilon} \parens{1 - \frac{1}{S} + \frac{L_{\max}}{\varepsilon S} \parens{\delta^0 + \Delta^*}} \times \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)}
    \end{align*}
    and is minimized by choosing
    \begin{align*}
        S^* = \frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}.
    \end{align*}
    Up to a constant factor, we get
    \begin{align*}
        T_{\textnormal{SGD}}(S^*, [\tau_i]_{i=1}^n) = \frac{\delta^0 L_-}{\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j}}.
    \end{align*}
\end{theorem}

\begin{proof}
    At each iteration, the algorithm needs to collect a minibatch of stochastic gradients of size $S$. Multiplying the iteration complexity of Theorem~\ref{thm:sgd} by the time needed to gather such a minibatch (Theorem~\ref{thm:batch}), the resulting time complexity is
    \begin{align*}
        T_{\textnormal{SGD}}(S, [\tau_i]_{i=1}^n) &= \frac{\delta^0 L_-}{\varepsilon} \parens{1 - \frac{1}{S} + \frac{L_{\max}}{\varepsilon S} \parens{\delta^0 + \Delta^*}} \times \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)}.
    \end{align*}

        We now find the optimal $S$. Assume first that $\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} \leq \frac{1}{2}$. Assumption~\ref{as:worker_smooth} ensures that the function $f$ is $L_{\max}$-smooth. Thus, we have $\norm{\nabla f(x^0)}^2 \leq 2L_{\max} \delta^0 \leq \varepsilon,$
        and $x^0$ is an $\varepsilon$-solution. Therefore, we can take any $S \geq 1.$

        Now, suppose that $\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} > \frac{1}{2}$. Then we have
        \begin{align*}
            T_{\textnormal{SGD}}(\nicefrac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}, [\tau_i]_{i=1}^n) &= \frac{\delta^0 L_-}{\varepsilon} \parens{2 - \frac{1}{S}} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j}} \\
            &\leq \frac{2\delta^0 L_-}{\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j}}.
        \end{align*}
        For all $S > \max\left\{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}, 1\right\},$ we get $S \geq 2$ and hence
        \begin{align*}
            T_{\textnormal{SGD}}(S, [\tau_i]_{i=1}^n) &= \frac{\delta^0 L_-}{\varepsilon} \parens{1 - \frac{1}{S} + \frac{L_{\max}}{\varepsilon S} \parens{\delta^0 + \Delta^*}} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)} \\
            &\geq \frac{\delta^0 L_-}{2\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)} \\
            &\geq \frac{\delta^0 L_-}{2\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j}}.
        \end{align*}
        Let us now consider the case $1 < S \leq \max\left\{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}, 1\right\}.$ We can additionally assume that $\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} > 1$ and $S \leq \frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}$ (otherwise, the set $S$ that satisfies the condition $1 < S \leq \max\left\{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}, 1\right\}$ is empty). We get
        \begin{align*}
            T_{\textnormal{SGD}}(S, [\tau_i]_{i=1}^n) &= \frac{\delta^0 L_-}{\varepsilon} \parens{1 - \frac{1}{S} + \frac{L_{\max}}{\varepsilon S} \parens{\delta^0 + \Delta^*}} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)} \\
            &\geq \frac{\delta^0 L_-}{\varepsilon} \parens{\frac{L_{\max}}{\varepsilon S} \parens{\delta^0 + \Delta^*}} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (S+j)} \\
            &= \frac{\delta^0 L_-}{\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j \frac{L_{\max}}{\varepsilon S} \parens{\delta^0 + \Delta^*}}} \\
            &\geq \frac{\delta^0 L_-}{\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j}}.
        \end{align*}
        Finally, for $S=1,$ we have
        \begin{align*}
            T_{\textnormal{SGD}}(S, [\tau_i]_{i=1}^n) &= \frac{\delta^0 L_- L_{\max}}{\varepsilon^2} \parens{\delta^0 + \Delta^*} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} (1+j)} \\
            &= \frac{\delta^0 L_-}{\varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + \frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} j}} \\
            &\geq \frac{\delta^0 L_-}{2 \varepsilon} \min_{j\in[n]} \parens{\parens{\sum_{i=1}^j \frac{1}{\tau_i}}^{-1} \parens{\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} + j}}
        \end{align*}
        because we assume $\frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*} > \frac{1}{2}.$ Therefore, an optimal choice is $S^* = \frac{L_{\max}}{\varepsilon} \parens{\delta^0 + \Delta^*}$.
\end{proof}






