\section{Setup of the Experiments from Section~\ref{sec:exp_quad}}
\label{sec:exp:setup}
We consider the optimization problem \eqref{eq:problem} with nonconvex quadratic functions. The matrices and vectors defining the objective functions $f_i$ are generated using Algorithm~\ref{algorithm:matrix_generation} with $m = 10000,$ $d = 1000,$ $\lambda = 1\mathrm{e}{-6},$ and $s = 10$. The output is used to construct
\begin{align*}
    f_i(x) = \frac{1}{2} x^\top \mA_i x - b_i^\top x \quad \forall x \in \R^d, \, \forall i \in [m].
\end{align*}

\begin{algorithm}[H]
\caption{Quadratic optimization task generation}
\label{algorithm:matrix_generation}
\begin{algorithmic}[1]
\State \textbf{Parameters:} number of functions $m$, dimension $d$, regularizer $\lambda$, noise scale $s$
\For{$i = 1, \dots, m$}
\State Generate random noises $\nu_i^s = 1 + s \xi_i^s$ and $\nu_i^b = s \xi_i^b,$ i.i.d. $\xi_i^s, \xi_i^b \sim \cN(0, 1)$
\State Let $b_i = \frac{\nu_i^s}{4}(-1 + \nu_i^b, 0, \cdots, 0) \in \R^{d}$
\State Take the initial tridiagonal matrix
\[\mA_i = \frac{\nu_i^s}{4}\left( \begin{array}{cccc}
    2 & -1 & & 0\\
    -1 & \ddots & \ddots & \\
    & \ddots & \ddots & -1 \\
    0 & & -1 & 2 \end{array} \right) \in \R^{d \times d}\]
\EndFor
\State Take the mean of matrices $\mA = \frac{1}{m}\sum_{i=1}^m \mA_i$
\State Find the minimum eigenvalue $\lambda_{\min}(\mA)$
\For{$i = 1, \dots, m$}
\State Update matrix $\mA_i = \mA_i + (\lambda - \lambda_{\min}(\mA)) \mI$
\EndFor
\State Take starting point $x^0 = (\sqrt{d}, 0, \cdots, 0)$
\State \textbf{Output:} matrices $\mA_1, \cdots, \mA_m$, vectors $b_1, \cdots, b_m$, starting point $x^0$
\end{algorithmic}
\end{algorithm}

