\section{Lower bound}
\label{sec:lower_bound_appendix}

\subsection{Time multiple oracles protocol}
\label{sec:lower_bound_formal}

The classical lower bound frameworks \citep{nemirovskij1983problem, carmon2020lower, arjevani2022lower,nesterov2018lectures} are not convenient in the analysis of parallel algorithms since they are designed to estimate lower bounds on \emph{iteration complexities}. In order to obtain \emph{time complexity} lower bounds, we use the framework by \citet{tyurin2023optimal}. Let us briefly explain the main idea. A more detailed explanation can be found in \citep{tyurin2023optimal}[Sections 3-6].

We start by introducing an appropriate oracle for our setup:
\begin{align*}
  O_{\tau}\,:\, &\underbrace{\R_{\geq 0}}_{\textnormal{time}} \times \underbrace{\R^d}_{\textnormal{point}} \times \underbrace{(\R_{\geq 0} \times \R^d \times \{0, 1\})}_{\textnormal{input state}} \rightarrow \underbrace{(\R_{\geq 0} \times \R^d \times \{0, 1\})}_{\textnormal{output state}} \times \R^d
\end{align*}
\begin{align}
  \label{eq:oracle_inside_random}
  \begin{split}
      &\textnormal{such that } \qquad O_{\tau}(t, x, (s_t, s_x, s_q)) = \left\{
  \begin{aligned}
      &((t, x, 1), &0), \quad & s_q = 0, \\
      &((s_t, s_x, 1), &0), \quad & s_q = 1, t < s_t + \tau,\\
      &((0, 0, 0), & \nabla f_j(s_x)), \quad & s_q = 1, t \geq s_t + \tau,\\
  \end{aligned}
  \right.
  \end{split}
\end{align}
where $j \sim \textnormal{Uniform}([m]),$ i.e., $j$ is a random index sampled uniformly from the set $[m]$. We assume that all draws from $\textnormal{Uniform}([m])$ are i.i.d..

Next, we define the \emph{time multiple oracles protocol}, first introduced in \citep{tyurin2023optimal}.

\begin{protocol}[H]
    \caption{Time Multiple Oracles Protocol}
    \label{alg:time_multiple_oracle_protocol}
    \begin{algorithmic}[1]
    \State \textbf{Input: }function $f = \frac{1}{m} \sum_{i=1}^{m} f_i,$ oracles and distributions $(O_1, ..., O_n) \in \cO(f),$ algorithm $A~\in~\cA$
    \State $s^0_i = 0$ for all $i \in [n]$
    \For{$k = 0, \dots, \infty$}
    \State $({t^{k+1}}, {i^{k+1}}, x^k) = A^k(g^1, \dots, g^{k}),$ \hfill $\rhd \,{t^{k+1} \geq t^{k}}$
    \State $(s^{k+1}_{{i^{k+1}}}, g^{k+1}) = O_{{i^{k+1}}}({t^{k+1}}, x^k, s^{k}_{{i^{k+1}}})$ \hfill $\rhd\,s^{k+1}_j = s^{k}_j \quad \forall j \neq i^{k+1}$
    \EndFor
    \end{algorithmic}
\end{protocol}

Let us explain the behavior of the protocol. At each iteration, the algorithm $A$ returns three outputs, based on the available information/gradients: time $t^{k+1},$ the index of a worker $i^{k+1},$ and a new point $x^k.$ Depending on the current time $t^{k+1}$ and the state of the worker, three options are possible (see~\eqref{eq:oracle_inside_random}). If $s_q = 0,$ then the worker is idle. It then starts calculations at the point $x^k,$ changes the state $s_q$ from $0$ to $1,$ stores the point $x^k$ in $s_x$ (at which a new stochastic gradient should be calculated), and returns a zero vector. If $s_q = 0$ and $t^{k+1} < s_t + \tau,$ then the worker is still calculating a stochastic gradient. It does not change the state and returns a zero vector because the computation has not finished yet. If $s_q = 0$ and $t^{k+1} \geq s_t + \tau,$ the worker can finally return a stochastic gradient at $s_x$ because sufficient time has passed since the worker was idle ($s_q = 0$). Note that with this oracle, the algorithm will never receive the first stochastic gradient before time $\tau$ (assuming that all oracles have the same processing time $\tau;$ in general, we will assume that the processing times are different). 

In the setting considered in this work, there are $n$ oracles that can do calculations in parallel, and an algorithm orchestrates their work. Let the processing times of the oracles be equal to $\tau_1, \dots, \tau_n.$ A reasonable strategy would be to call each oracle with $t^k = 0,$ then to call the fastest worker with $t^k = \min_{i \in [n]} \tau_i$ to get the first stochastic gradients as soon as possible, then to call this worker again with $t^k = \min_{i \in [n]} \tau_i$ to request calculation of the next stochastic gradient, and so on.
One unusual thing about this protocol is that the algorithm controls the time. The oracle is designed to force the algorithm to increase the time; otherwise, the algorithm would not receive new information about the function.

Our goal will be to bound the complexity measure $\mathfrak{m}_{\textnormal{time}}\left(\cA, \cF\right)$, defined as
\begin{align}\label{eq:lower_compl_time}
    \begin{split}
    &\mathfrak{m}_{\textnormal{time}}\left(\cA, \cF\right) \eqdef \inf_{A \in \cA} \sup_{f \in \cF} \sup_{\{O_i\} \in \cO(f)} \inf\left\{t \geq 0\,\middle|\,\Exp{ \inf_{k \in S_t}\norm{\nabla f(x^k)}^2} \leq \varepsilon \right\}, 
    \\
    &S_t \eqdef \left\{k \in \N_0 \middle| t^{k} \leq t\right\},
\end{split}
\end{align}
where the sequences $t^k$ and $x^k$ are generated by Protocol~\ref{alg:time_multiple_oracle_protocol}. Hence, unlike the classical approach, where the lower bounds are obtained for the minimum number of iterations required to find an $\varepsilon$--stationary point, we seek to find the minimum \emph{time} needed to get an $\varepsilon$--stationary point.

We consider a standard for our setup class of functions \citep{fang2018spider}:

\begin{definition}[Function Class $\cF^m_{\delta^0, L_+}$]
  We say that $f \in \cF^m_{\delta^0, L_+}$ if it is $\delta^0$-bounded, i.e., $f(0) - \inf_{x \in \R^d} f(x) \leq \delta^0$, and
  $$f(x) = \frac{1}{m} \sum_{i=1}^{m} f_i(x),$$
  where the functions $f_i \,:\,\R^d \rightarrow \R$ are differentiable and satisfy
  $$\frac{1}{m} \sum_{i=1}^{m} \norm{\nabla f_i(x) - \nabla f_i(y)}^2 \leq L_+^2 \norm{x - y}^2 \quad \forall x, y \in \R^d.$$
  \label{def:func_class}
\end{definition}

Next, we define the class of algorithms we will analyze.

\begin{definition}[Algorithm Class $\cA_{\textnormal{zr}}$]
  \label{def:alg_class}
  Let us consider Protocol~\ref{alg:time_multiple_oracle_protocol}. We say that a sequence of mappings $A = \{A^k\}_{k=0}^{\infty}$ is a \emph{zero-respecting algorithm}, if
  \begin{enumerate}
    \item $A^k\,:\, \underbrace{\R^d \times \dots \times \R^d}_{k \textnormal{ times}} \rightarrow \R_{\geq 0} \times \N \times \R^d$ for all $k \geq 1$ and $A^0 \in \R_{\geq 0} \times \N \times \R^d.$ \label{prop:one}
    \item For all $k \geq 1$ and $g^1, \dots, g^k \in \R^d,$ $t^{k+1} \geq t^k,$
    where $t^{k+1}$ and $t^k$ are defined as $(t^{k+1}, \dots) = A^k(g^1, \dots, g^k)$ and $(t^k, \dots) = A^{k-1}(g^1, \dots, g^{k-1}).$ \label{prop:two}
    \item $\textnormal{supp} \left(x^k\right) \subseteq \bigcup_{j = 1}^k \textnormal{supp} \left(g^j\right)$ 
    for all $k \in \N_0,$ where $\textnormal{supp}(x) \eqdef \{i \in [d]\,|\,x_i \neq 0\}.$ \label{prop:four}
  \end{enumerate}
  We denote the set of all algorithms with these properties as $\cA_{\textnormal{zr}}.$
\end{definition}

In the above definition, property \ref{prop:one} defines the domain of the mappings $A^k$, and property \ref{prop:two} ensures that our algorithm does not ``cheat'' and does not ``travel into the past'': the time can only go forward (see \citep{tyurin2023optimal}[Section 4, Definition 4.1]). Property \ref{prop:four} is a standard assumption for zero-respecting algorithms \citep{arjevani2022lower} that is satisfied by virtually all algorithms, including \algname{Adam} \citep{kingma2014adam}, \algname{SGD}, \algname{PAGE} \citep{li2021page} and \algname{Asynchronous SGD}.

It remains to define an oracle class for our problem that employs oracles from \eqref{eq:oracle_inside_random}. We design oracles that emulate the real behavior of the workers.
\begin{definition}[Computation Oracle Class $\cO_{\tau_1, \dots, \tau_n}$]
  For any $f \in \cF^m_{\delta^0, L_+},$ the oracle class $\cO_{\tau_1, \dots, \tau_n}$ returns oracles $O_i = O_{\tau_i}$, $i \in [n]$, where the mappings $O_{\tau_i}$ are defined in \eqref{eq:oracle_inside_random}.
  \label{def:oracle_class}
\end{definition}

\subsection{The ``worst case'' function in the nonconvex world}
\label{sec:worst_case}

The analysis uses a standard function, commonly employed to derive lower bounds in the nonconvex regime. First, let us define
\begin{align*}
    \textnormal{prog}(x) \eqdef \max \{i \geq 0\,|\,x_i \neq 0\} \quad (x_0 \equiv 1).
\end{align*}
Our choice of the underlying function $F$ follows the construction introduced in \citet{carmon2020lower,arjevani2022lower}: for any $T \in \N,$ define
\begin{align}
    \label{eq:worst_case}
    F_T(x) \eqdef -\Psi(1) \Phi(x_1) + \sum_{i=2}^T \left[\Psi(-x_{i-1})\Phi(-x_i) - \Psi(x_{i-1})\Phi(x_i)\right],
\end{align}
where
\begin{align*}
    \Psi(x) = \begin{cases}
        0, & x \leq 1/2, \\
        \exp\left(1 - \frac{1}{(2x - 1)^2}\right), & x \geq 1/2,
    \end{cases}
    \quad\textnormal{and}\quad
    \Phi(x) = \sqrt{e} \int_{-\infty}^{x}e^{-\frac{1}{2}t^2}dt.
\end{align*}
Throughout the proof, we only rely on the following properties of the function:
\begin{lemma}[\cite{carmon2020lower, arjevani2022lower}]
    \label{lemma:worst_function}
    The function $F_T$ satisfies:
    \begin{enumerate}
        \item $F_T(0) - \inf_{x \in \R^T} F_T(x) \leq \Delta^0 T,$ where $\Delta^0 = 12.$
        \item The function $F_T$ is $l_1$--smooth, where $l_1 = 152.$
        \item For all $x \in \R^T,$ $\norm{\nabla F_T(x)}_{\infty} \leq \gamma_{\infty},$ where $\gamma_{\infty} = 23.$
        \item For all $x \in \R^T,$ $\textnormal{prog}(\nabla F_T(x)) \leq \textnormal{prog}(x) + 1.$
        \item For all $x \in \R^T,$ if $\textnormal{prog}(x) < T,$ then $\norm{\nabla F_T(x)} > 1.$
    \end{enumerate}
\end{lemma}


\subsection{The first lower bound}\label{sec:lower_bound1}

We are ready to present the main results of this section.

\begin{restatable}{theorem}{THEOREMLOWERBOUND}
  \label{theorem:lower_bound}
  Let us consider Protocol~\ref{alg:time_multiple_oracle_protocol}. Without loss of generality, assume that $0 < \tau_1 \leq \dots \leq \tau_n$ and take any $L_{+}, \delta^0, \varepsilon > 0,$ and $m \in \N$ such that $\varepsilon < c_1 L_{+} \delta^0$ and $\frac{\delta^0 L_+}{\varepsilon} > c_2 \sqrt{m}.$ Then, for any algorithm $A \in \cA_{\textnormal{zr}},$ there exists a function $f \in \cF^m_{\delta^0, L_+}$ and computation oracles $(O_1, \dots, O_n) \in \cO_{\tau_1, \dots, \tau_n}(f)$ such that $\Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} > \varepsilon,$ 
  where $S_t \eqdef \left\{k \in \N_0 \,|\,t^k \leq t\right\}$ and 
$$t = c_3 \times \frac{\delta^0 L_+}{\sqrt{m} \varepsilon} \min_{j \in [n]} \left[\left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(m + j\right)\right].$$
The quantities $c_1,$$c_2,$ and $c_3$ are universal constants. The sequences $x^k$ and $t^k$ are defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
\end{restatable}

\begin{proof}
    \textbf{(Step 1: Construction of a hard problem)}\\
    We start our proof by constructing an appropriate function $f \in \cF^m_{\delta^0, L_+}.$ Let us fix any $T \geq \N$ and define $f_i \,:\,\R^T \rightarrow \R$ such that
    \begin{align*}
        f_1 \eqdef \frac{\sqrt{m} L_+ \lambda^2}{l_1} F_T\left(\frac{x}{\lambda}\right) 
    \end{align*}
    for all $x \in \R^T,$ and $f_i(x) = 0$ for all $i \in \{2, \dots, m\}$ and $x \in \R^T.$ Essentially, all information about the function $f = \frac{1}{m} \sum_{i=1}^{m} f_i$ is in the first function. Note that
    \begin{align*}
        \frac{1}{m} \sum_{i=1}^{m} \norm{\nabla f_i(x) - \nabla f_i(y)}^2 
        &= \frac{1}{m} \norm{\nabla f_1(x) - \nabla f_1(y)}^2 \\
        &= \frac{1}{m} \norm{\frac{\sqrt{m} L_+ \lambda}{l_1} \nabla F_T\left(\frac{x}{\lambda}\right) - \frac{\sqrt{m} L_+ \lambda}{l_1} \nabla F_T\left(\frac{y}{\lambda}\right)}^2 \\
        &= \frac{L_+^2 \lambda^2}{l_1^2}  \norm{\nabla F_T\left(\frac{x}{\lambda}\right) - \nabla F_T\left(\frac{y}{\lambda}\right)}^2.
    \end{align*}
    Then, using Lemma~\ref{lemma:worst_function}, we have
    \begin{align}
        \label{eq:oZptwxozdpoFk}
        \frac{1}{m} \sum_{i=1}^{m} \norm{\nabla f_i(x) - \nabla f_i(y)}^2 
        \leq L_+^2 \lambda^2  \norm{\frac{x}{\lambda} - \frac{y}{\lambda}}^2 = L_+^2 \norm{x - y}^2.
    \end{align}
    Taking
    \begin{align*}
        T = \flr{\frac{\sqrt{m} \delta^0 l_1}{L_+ \lambda^2 \Delta^0}},
    \end{align*}
    we ensure that
    \begin{align}
        \label{eq:eqhNFkSc}
        f(0) - \inf_{x \in \R^T} f(x) &= \frac{1}{m} \left(\frac{\sqrt{m} L_+ \lambda^2}{l_1} F_T\left(0\right) - \inf_{x \in \R^T} \frac{\sqrt{m} L_+ \lambda^2}{l_1} F_T\left(x\right)\right) \nonumber\\
        &= \frac{L_+ \lambda^2}{\sqrt{m} l_1} \left(F_T\left(0\right) - \inf_{x \in \R^T} F_T\left(x\right)\right) \leq \frac{L_+ \lambda^2 \Delta^0 T}{\sqrt{m} l_1} \leq \delta^0,
    \end{align}
    where in the inequalities we use Lemma~\ref{lemma:worst_function} and the choice of $T.$ Now, inequalities \eqref{eq:oZptwxozdpoFk} and \eqref{eq:eqhNFkSc} imply that $f = \frac{1}{m} \sum_{i=1}^{m} f_i \in \cF^m_{\delta^0, L_+}$, and hence, using Lemma~\ref{lemma:worst_function} again, we get
    \begin{align*}
        \inf_{k \in S^t} \norm{\nabla f(x^k)}^2 &= \inf_{k \in S^t} \norm{\frac{1}{m} \times \frac{\sqrt{m} L_+ \lambda}{l_1} \nabla F_T\left(\frac{x^k}{\lambda}\right)}^2 \\
        &= \frac{L_+^2 \lambda^2}{m l_1^2} \inf_{k \in S^t} \norm{\nabla F_T\left(\frac{x}{\lambda}\right)}^2 > \frac{L_+^2 \lambda^2}{m l_1^2} \inf_{k \in S^t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right].
    \end{align*}
    Let us take 
    \begin{align*}
        \lambda = \frac{2 l_1 \sqrt{m}\sqrt{\varepsilon}}{L_+}.
    \end{align*}
    Then 
    \begin{align}
        \label{eq:YfxCfV}
        \inf_{k \in S^t} \norm{\nabla f(x^k)}^2 > 4 \varepsilon \inf_{k \in S^t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right]
    \end{align}
    and
    \begin{align*}
        T = \flr{\frac{\delta^0 L_+}{4 l_1 \Delta^0 \sqrt{m} \varepsilon}}.
    \end{align*}
    The last inequality means that while $\textnormal{prog}(x^k) < T$ for all $k \in S^t,$ all gradients are large. The function $F_T$ is a \emph{zero-chain}: due to Lemma~\ref{lemma:worst_function}, we know that $\textnormal{prog}(\nabla F_T(x)) \leq \textnormal{prog}(x) + 1$ for all $x \in \R^T.$ This implies that we can discover at most one new non-zero coordinate by calculating the gradient of the function $\nabla f_1.$ Since the algorithm $A \in \cA_{\textnormal{zr}}$ is zero-respecting, by definition it cannot return a point $x^k$ with progress greater than that of the vectors returned by the oracles. In view of this, it is necessary to calculate the gradient of $f_1$ at least $T$ times to get $\textnormal{prog}(x^k) \geq T.$

    The gradient of $f_1$ can be calculated if and only if $j = 1,$ where $j \sim \textnormal{Uniform}([m])$ (see \eqref{eq:oracle_inside_random}).
    Consider worker $i$ and define $\eta_i^1$ to be the number of draws from $\textnormal{Uniform}([m])$ until the index $j = 1$ is sampled. Clearly, $\eta_i^1$ is a Geometric random variable with parameter $\Prob{j = 1} = \frac{1}{m}.$ Recall that the workers can do the computations in parallel, and by the design of the oracles, worker $i$ needs at least $\tau_i \eta_i^1$ seconds to calculate $\eta_i^1$ stochastic gradients.
    Hence, it is impossible to calculate $\nabla f_1$ before the time
    \begin{align*}
        \min_{i \in [n]} \tau_i \eta_i^1.
    \end{align*}    
    Once the algorithm calculates $\nabla f_1$ for the first time, it needs to do so at least $T - 1$ times more to achieve $\textnormal{prog}(x^k) \geq T.$ Thus, one should wait at least 
    \begin{align*}
        \sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k
    \end{align*}
    seconds, where $\eta_i^k \overset{\textnormal{i.i.d.}}{\sim} \textnormal{Geometric}(\nicefrac{1}{m})$. We can conclude that
    \begin{align}
        \label{eq:aGAVfIUGkbWG}
        \Prob{\inf_{k \in S^t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] = 0} \leq \Prob{\sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k \leq t}.
    \end{align} \\
    \textbf{(Step 2: The Chernoff Method)}\\
    The theorem's proof is now reduced to the analysis of the concentration of $\sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k.$
    Using the Chernoff method, for all $s >0$, we have 
    \begin{align*}
        \Prob{\sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k \leq t} &= \Prob{- s \sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k \geq - s t} \\
        &= \Prob{e^{- s \sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k} \geq e^{- s t}} \\
        &\leq e^{s t} \Exp{\exp\left(- s \sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k\right)}.
    \end{align*}
    Independence gives
    \begin{align}
        \label{eq:IuiyqWW}
        \Prob{\sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k \leq t}
        &\leq e^{s t} \prod_{k=1}^{T} \Exp{\exp\left(- s \min_{i \in [n]} \tau_i \eta_i^k\right)} \nonumber\\
        &\overset{\textnormal{i.i.d.}}{=}  e^{s t} \left(\Exp{\exp\left(- s \min_{i \in [n]} \tau_i \eta_i^1\right)}\right)^T.
    \end{align}
    Let us consider the term in the last bracket separately. For a fixed $t' > 0$, we have
    \begin{eqnarray}
        &&\hspace{-1cm}\Exp{\exp\left(- s \min_{i \in [n]} \tau_i \eta_i^1\right)} \\
        &=& \Exp{\max_{i \in [n]}\exp\left(- s \tau_i \eta_i^1\right)} \nonumber\\
        &=& \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right] \exp\left(- s \tau_i \eta_i^1\right) + \left(1 - \mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right) \exp\left(- s \tau_i \eta_i^1\right)\right)} \nonumber \\
        &\leq& \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right] + \left(1 - \mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right) \exp\left(- s t'\right)\right)} \nonumber \\
        &=& \exp\left(- s t'\right) + (1 - \exp\left(- s t'\right)) \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right)}.
    \label{eq:xOIbDHbliybIEmlrat}
    \end{eqnarray}

    We now consider the last term. Due to the independence, we have
    \begin{align*}
        \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right)} 
        = 1 - \prod_{i=1}^n \Prob{\tau_i \eta_i^1 > t'}
        = 1 - \prod_{i=1}^n \left(1 - p\right)^{\flr{\frac{t'}{\tau_i}}},
    \end{align*}
    where we use the cumulative distribution function of a geometric random variable and temporarily define $p \eqdef \frac{1}{m}.$ Using Lemma~\ref{lemma:sum_prod}, we get
    \begin{align}
        \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right)} \leq p \sum_{i=1}^{n} \flr{\frac{t'}{\tau_i}}.
        \label{eq:bNNMYRoZFUY}
    \end{align}
    Let us take 
    \begin{align*}
        t' = \frac{1}{8} \times \min_{j \in [n]} \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + j\right) = \frac{1}{8} \times \min_{j \in [n]} g(j),
    \end{align*}
    where $g(j) \eqdef \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + j\right)$ for all $j \in [n]$ and assume that $j^*$ is the largest index such that $\min_{j \in [n]} g(j) = g(j^*).$ Then, Lemma \ref{lemma:techn1} gives
    \begin{align}
        \label{eq:STaSs}
        \tau_{j^*} \leq \min_{j \in [n]} g(j) < \tau_{j^* + 1},
    \end{align}
    where we let $\tau_{n + 1} \equiv \infty$. Therefore, $t' < \tau_{j^* + 1}$ and \eqref{eq:bNNMYRoZFUY} gives
    \begin{align*}
        \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right)} 
        &\leq p \sum_{i=1}^{n} \flr{\frac{t'}{\tau_i}} = p \sum_{i=1}^{j^*} \flr{\frac{t'}{\tau_i}}.
    \end{align*}
    Using \eqref{eq:STaSs}, we get $\frac{t'}{\tau_i} = \frac{\min_{j \in [n]} g(j)}{8 \tau_i} \geq \frac{1}{8}$ for all $i \leq j^*.$
    Since $\flr{x} \leq 2 x - \frac{1}{4}$ for all $x \geq \frac{1}{8},$ we obtain
    \begin{align*}
        \Exp{\max_{i \in [n]} \left(\mathbbm{1}\left[\tau_i \eta_i^1 \leq t'\right]\right)} 
        &\leq p \sum_{i=1}^{j^*} \left(\frac{2 t'}{\tau_i} - \frac{1}{4}\right) = 2 p t' \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) - \frac{p j^*}{4} \\
        &=2 p \times \frac{1}{8} \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + j^*\right) \times \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right) - \frac{p j^*}{4} \\
        &=\frac{p}{4} \left(\frac{1}{p} + j^*\right) - \frac{p j^*}{4} = \frac{1}{4}.
    \end{align*}
    Substituting the last inequality to \eqref{eq:xOIbDHbliybIEmlrat} gives
    \begin{align*}
        \Exp{\exp\left(- s \min_{i \in [n]} \tau_i \eta_i^1\right)} 
        &\leq \exp\left(- s t'\right) + \frac{1}{4} (1 - \exp\left(- s t'\right)).
    \end{align*}
    We now take $s = 1 / t'$ to obtain
    \begin{align*}
        \Exp{\exp\left(- s \min_{i \in [n]} \tau_i \eta_i^1\right)} \leq e^{-1} + \frac{1}{4} (1 - e^{-1}) \leq e^{-\frac{1}{2}}.
    \end{align*}
    Substituting this inequality in \eqref{eq:aGAVfIUGkbWG} and \eqref{eq:IuiyqWW} gives
    \begin{align*}
        \Prob{\inf_{k \in S^t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] = 0} \leq \Prob{\sum_{k=1}^{T} \min_{i \in [n]} \tau_i \eta_i^k \leq t} \leq e^{\frac{t}{t'} - \frac{T}{2}}.
    \end{align*}
    Therefore,
    \begin{align*}
        \Prob{\inf_{k \in S^t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] = 0} \leq \rho
    \end{align*}
    for all 
    \begin{align*}
        t \leq \frac{1}{8} \min_{j \in [n]} \left[\left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + j\right)\right] \left(\frac{T}{2} + \log \rho\right)
    \end{align*}
    and $\rho > 0.$ Using the bound on the probability with $\rho = \frac{1}{2}$ and \eqref{eq:YfxCfV}, we finally conclude 
    \begin{align*}
        \Exp{\inf_{k \in S^t} \norm{\nabla f(x^k)}^2} > 4 \varepsilon \Prob{\inf_{k \in S^t} \mathbbm{1}\left[\textnormal{prog}(x^k) < T\right] = 1} \geq 2 \varepsilon
    \end{align*}
    for all
    \begin{align*}
        t 
        &\leq \frac{1}{8} \min_{j \in [n]} \left[\left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(\frac{1}{p} + j\right)\right] \left(\frac{T}{2} + \log \frac{1}{2}\right) \\
        &= \frac{1}{8} \min_{j \in [n]} \left[\left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(m + j\right)\right] \left(\frac{1}{2} \flr{\frac{\delta^0 L_+}{4 l_1 \Delta^0 \sqrt{m} \varepsilon}} + \log \frac{1}{2}\right).
    \end{align*}
    It remains to use the conditions $\varepsilon < c_1 L \delta^0$ and $\frac{\delta^0 L_+}{\varepsilon} > c_2 \sqrt{m}$ from the theorem to finish the proof.
\end{proof}

\subsection{The second lower bound}\label{sec:lower_bound2}

\begin{restatable}{theorem}{THEOREMLOWERBOUNDSECOND}
    \label{theorem:second_lower_bound}
    Let us consider Protocol~\ref{alg:time_multiple_oracle_protocol}. Without loss of generality, assume that $0 < \tau_1 \leq \dots \leq \tau_n$ and take any $L_{+}, \delta^0, \varepsilon > 0,$ and $m \in \N$ such that $\varepsilon < c_1 L_{+} \delta^0.$ Then, for any algorithm $A \in \cA_{\textnormal{zr}},$ there exists a function $f \in \cF^m_{\delta^0, L_+}$ and computation oracles $(O_1, \dots, O_n) \in \cO_{\tau_1, \dots, \tau_n}(f)$ such that $\Exp{\inf_{k \in S_t} \norm{\nabla f(x^k)}^2} > \varepsilon,$ 
    where $S_t \eqdef \left\{k \in \N_0 \,|\,t^k \leq t\right\}$ and 
  $$t = c_2 \times \min_{j \in [n]} \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(m + j\right).$$
  The quantities $c_1$ and $c_2$ are universal constants. The sequences $x^k$ and $t^k$ are defined in Protocol~\ref{alg:time_multiple_oracle_protocol}.
\end{restatable}

\begin{proof}
    We use the same construction as in the proof of Theorem $2$ of \citet{li2021page}. Let us consider 
    \begin{align}\label{eq:worst_case_f2}
        f_i(x) \eqdef c \inp{v_i}{x} + \frac{L_{+}}{2} \norm{x}^2
    \end{align}
    for all $x \in \R^{T},$ where $c \in \R$ and $v_i \in \R^{T}$, $i \in [n]$ are parameters that we define later.
    Then 
    \begin{align*}
        \frac{1}{m} \sum_{i=1}^{m} \norm{\nabla f_i(x) - \nabla f_i(y)}^2 \leq L_{+}^2 \norm{x - y}^2
    \end{align*}
    for all $x, y \in \R^d$ and 
    \begin{align*}
        f(0) - \inf_{x \in \R^T} f(x) = - \inf_{x \in \R^T} \left[c \inp{\frac{1}{m} \sum_{i=1}^{m} v_i}{x} + \frac{L_{+}}{2} \norm{x}^2\right] 
        = \frac{c^2}{2 L_{+} m^2} \norm{\sum_{i=1}^{m} v_i}^2 = \delta^0,
    \end{align*}
    where we take 
    \begin{align*}
        c \eqdef \sqrt{\frac{2 L_{+} m^2\delta^0}{\norm{\sum_{i=1}^{m} v_i}^2}}.
    \end{align*}
    Thus, we have $f = \frac{1}{m} \sum_{i=1}^{m} f_i \in \cF^m_{\delta^0, L_+}.$ Now, let 
    \begin{align*}
        &v_1 = (\underbrace{1, \dots, 1}_{\frac{T}{m}}, 0, \dots, 0)^\top \in \R^T, \\
        &v_2 = (\underbrace{0, \dots, 0}_{\frac{T}{m}}, \underbrace{1, \dots, 1}_{\frac{T}{m}}, 0, \dots, 0)^\top \in \R^T, \\
        &v_3 = (\underbrace{0, \dots, 0}_{\frac{T}{m}}, \underbrace{0, \dots, 0}_{\frac{T}{m}}, \underbrace{1, \dots, 1}_{\frac{T}{m}}, 0, \dots, 0)^\top \in \R^T \\
        &\dots  \\
        &v_n = (0, \dots, 0, \underbrace{1, \dots, 1}_{\frac{T}{m}})^\top \in \R^T.
    \end{align*}
    and choose any $T \in \{s m \,|\, s \in \N\}$ (one can always take $T = m$).
    Then 
    \begin{align*}
        c = \sqrt{\frac{2 L_{+} m^2\delta^0}{T}}.
    \end{align*}
    Let us fix some time $t > 0$ to be determined later and recall that the workers can calculate the stochastic gradients $\nabla f_i(x) = c v_i + L_{+} x$ in parallel. Suppose that up to time $t$, fewer than $\frac{m}{2}$ stochastic gradients have been computed. Then, since the algorithm is a zero-respecting algorithm, it cannot have discovered more than $\frac{m}{2} \times \frac{T}{m} = \frac{T}{2}$ coordinates. Thus, at least $\frac{T}{2}$ coordinates are equal to $0$ and 
    \begin{align*}
        \norm{\nabla f(x^k)}^2 = \norm{\frac{c}{m} \sum_{i=1}^m v_i + L_{+} x^k}^2 \geq \frac{c^2}{m^2} \times \frac{T}{2}.
    \end{align*}
    for all $k \in \left\{k \in \N_0 \,|\,t^k \leq t\right\}$. Therefore, substituting our choice of $c$ and using the assumptions from the theorem, we get
    \begin{align}
        \label{eq:AzUpLSPcSM}
        \norm{\nabla f(x^k)}^2 \geq L_{+}\delta^0 > 2 \varepsilon.
    \end{align}

    It remains to find the time $t > 0.$ The workers work in parallel, so in $t$ seconds they calculate at most 
    \begin{align*}
        \sum_{i=1}^{n} \flr{\frac{t}{\tau_i}}
    \end{align*}
    stochastic gradients. Now, let
    \begin{align}
        \label{eq:KzAfFVwxs}
        t = \frac{1}{8} \min_{j \in [n]} \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(m + j\right),
    \end{align}
    and define $g(j) \eqdef \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(m + j\right)$ for all $j \in [n].$ Assume that $j^*$ is the largest index such that $\min_{j \in [n]} g(j) = g(j^*).$ Using Lemma~\ref{lemma:techn1}, we have
    \begin{align*}
        \sum_{i=1}^{n} \flr{\frac{t}{\tau_i}} = \sum_{i=1}^{j^*} \flr{\frac{t}{\tau_i}}.
    \end{align*}
    Since $\frac{t}{\tau_i} \geq \frac{1}{8}$ for all $i \leq j^*$ and $\flr{x} \leq 2 x - \frac{1}{4}$ for all $x \geq \frac{1}{8},$ we obtain
    \begin{align*}
        \sum_{i=1}^{n} \flr{\frac{t}{\tau_i}} \leq \sum_{i=1}^{j^*} \frac{2 t}{\tau_i} - \frac{j^*}{4} = \frac{1}{4} \left(\sum_{i=1}^{j^*} \frac{1}{\tau_i}\right)^{-1} \left(m + j^*\right) \sum_{i=1}^{j^*} \frac{1}{\tau_i} - \frac{j^*}{4} = \frac{m}{4}.
    \end{align*}
    Therefore, it is possible to calculate at most $\frac{m}{4}$ stochastic gradient in time \eqref{eq:KzAfFVwxs} and we can finally conclude that inequality \eqref{eq:AzUpLSPcSM} holds for any time that is less than or equal \eqref{eq:KzAfFVwxs}.
\end{proof}

