\section{Useful Identities and Inequalities}



\begin{lemma}[\citep{szlendak2021permutation}] \label{lemma:smoothness_consts}
    It holds that $L_- \leq L_+$, $L_- \leq \frac{1}{m} \sum_{i=1}^m L_i$ and $L_+^2 - L_-^2 \leq L_{\pm}^2 \leq L_+^2 \leq \frac{1}{m} \sum_{i=1}^m L_i^2$.
\end{lemma}



\begin{lemma}
\label{lemma:sum_prod}
Consider a sequence $q_1, \dots, q_n \in [0, 1]$. Then
\begin{align*}
    1 - \sum_{m=1}^n q_m \leq \prod_{m=1}^n \left(1  - q_m\right).
\end{align*}
\end{lemma}
\begin{proof}
We prove the result by induction. It is clearly true for $n = 1$: $1 - \sum_{m=1}^{1} q_m =\prod_{m=1}^1 \left(1  - q_m\right).$ Now, assume that that it holds for $n - 1$, meaning that
\begin{align*}
1 - \sum_{m=1}^{n-1} q_m \leq \prod_{m=1}^{n-1} \left(1  - q_m\right).
\end{align*}
Multiplying both sides of the inequality by $1 - q_n \in [0, 1]$ gives
\begin{align*}
\prod_{m=1}^{n} \left(1  - q_m\right) \geq \left(1 - q_n\right)\left(1 - \sum_{m=1}^{n-1} q_m\right) = 1 - \sum_{m=1}^{n-1} q_m - q_n + q_n \left(\sum_{m=1}^{n-1} q_m\right) \geq 1 - \sum_{m=1}^{n} q_m
\end{align*}
since $q_m \in [0, 1]$ for all $m \in [n].$
\end{proof}

\begin{theorem}
    \label{eq:simple_upper_bounds_for_eq_time}
    Let us consider the equilibrium time mapping from Definition~\ref{def:time_budget}. Then
    \begin{enumerate}
        \item $\Teq(S, [\tau_i]_{i=1}^{n}) \leq 2 \tau_n \max\left\{\frac{S}{n}, 1\right\}.$ \\ 
        \item $\Teq(S, [\tau_i]_{i=1}^{n}) \leq 2 \tau_1 \max\left\{S, 1\right\}$
    \end{enumerate}
    for all $S \geq 0,$ $\tau_i \in [0, \infty]$ for all $i \in [n],$ and $\tau_1 \leq \dots \leq \tau_n.$
\end{theorem}

\begin{remark}
    \label{remark:better}
    Assume that $\tau_1 = \dots = \tau_{n - 1} = \tau$ and $\tau_n \to \infty,$ then
    \begin{align*}
        \lim\limits_{\tau_n \to \infty} \Teq(S, [\tau_i]_{i=1}^{n}) = \Teq(S, [\tau_i]_{i=1}^{n - 1}) 
        = \tau\parens{\frac{S}{n - 1} + 1} \leq 2 \tau \max\left\{\frac{S}{n - 1}, 1\right\},
    \end{align*}
    \begin{align*}
        \lim\limits_{\tau_n \to \infty} 2 \tau_n \max\left\{\frac{S}{n}, 1\right\} = \infty,
    \end{align*}
    and
    \begin{align*}
        \lim\limits_{\tau_n \to \infty} 2 \tau_1 \max\left\{S, 1\right\} = 2 \tau \max\left\{S, 1\right\}.
    \end{align*}
    Thus, $\Teq(S, [\tau_i]_{i=1}^{n})$ can be arbitrarily smaller than $2 \tau_n \max\left\{\frac{S}{n}, 1\right\}$ and $2 \tau_1 \max\left\{S, 1\right\}.$ This implies that our new complexities \eqref{eq:best_time_comp} and \eqref{eq:time_comp} can be arbitrarily better than $T_{\textnormal{Soviet PAGE}}$ and $T_{\textnormal{Hero PAGE}}.$
\end{remark}

\begin{lemma}\label{lemma:techn1}
    Consider a sequence $0<\tau_1\leq\ldots\leq\tau_n$ and fix some $S>0$. For all $j \in [n]$, define $$g(j) \eqdef \left(\sum_{i=1}^j \frac{1}{\tau_i}\right)^{-1} \left(S + j\right).$$ 
    \begin{enumerate}
        \item Let $j^*_{\max}$ be the largest index such that $\min\limits_{j \in [n]} g(j) = g(j^*_{\max}).$ For $j^*_{\max} < n,$ we have
        \begin{align*}
            \min_{j \in [n]} g(j) < \tau_{(j^*_{\max} + 1)}.
        \end{align*}
        \item Let $j^*$ be any index such that $\min\limits_{j \in [n]} g(j) = g(j^*).$ For $j^* < n,$ we have
        \begin{align*}
            \min_{j \in [n]} g(j) \leq \tau_{(j^* + 1)}.
        \end{align*}
        \item Let $j^*_{\min}$ be the smallest index such that $\min\limits_{j \in [n]} g(j) = g(j^*_{\min})$. Then
        \begin{align*}
            \tau_{j^*_{\min}} < \min_{j \in [n]} g(j).
        \end{align*}
        \item Let $j^*$ be any index such that $\min\limits_{j \in [n]} g(j) = g(j^*).$ Then
        \begin{align*}
            \tau_{j^*} \leq \min_{j \in [n]} g(j).
        \end{align*}
    \end{enumerate}
\end{lemma}

\begin{proof}
    We first prove the first inequality.
    Suppose that $j^*_{\max} < n$. Then $g(j^*_{\max}) < g(j^*_{\max} + 1)$, meaning that
    \begin{align*}
        \left(\sum_{i=1}^{j^*_{\max}} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_{\max}\right) < \left(\sum_{i=1}^{j^*_{\max} + 1} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_{\max} + 1\right).
    \end{align*}
    This implies the following series of inequalities:
    \begin{align*}
        &\left(\sum_{i=1}^{j^*_{\max} + 1} \frac{1}{\tau_i}\right) \left(S + j^*_{\max}\right) < \left(\sum_{i=1}^{j^*_{\max}} \frac{1}{\tau_i}\right) \left(S + j^*_{\max} + 1\right) \\
        &\Leftrightarrow\quad \frac{1}{\tau_{(j^*_{\max} + 1)}} \left(S + j^*_{\max}\right) < \sum_{i=1}^{j^*_{\max}} \frac{1}{\tau_i} \\
        &\Leftrightarrow\quad \tau_{(j^*_{\max} + 1)} > \left(\sum_{i=1}^{j^*_{\max}} \frac{1}{\tau_i}\right)^{-1}\left(S + j^*_{\max}\right) = g(j^*_{\max}) = \min_{j \in [n]} g(j).
    \end{align*}
    The proof of the second inequality is the same, but with non-strict inequalities.
    To prove the third inequality, first suppose that $j^*_{\min} = 1$. Then $g(j^*_{\min}) = \tau_{j^*_{\min}} \left(S + 1\right) > \tau_{j^*_{\min}}$ as needed. On the other hand, $j^*_{\min} > 1$ implies
    \begin{align*}
        &g(j^*_{\min}) < g(j^*_{\min} - 1) \\
        &\Leftrightarrow \left(\sum_{i=1}^{j^*_{\min}} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_{\min}\right) < \left(\sum_{i=1}^{j^*_{\min} - 1} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_{\min} - 1\right) \\
        &\Leftrightarrow\quad \left(\sum_{i=1}^{j^*_{\min} - 1} \frac{1}{\tau_i}\right) \left(S + j^*_{\min}\right) < \left(\sum_{i=1}^{j^*_{\min}} \frac{1}{\tau_i}\right) \left(S + j^*_{\min} - 1\right) \\
        &\Leftrightarrow\quad \sum_{i=1}^{j^*_{\min}} \frac{1}{\tau_i} < \frac{1}{\tau_{j^*_{\min}}} \left(S + j^*_{\min}\right) \\
        &\Leftrightarrow\quad \tau_{j^*_{\min}} < \left(\sum_{i=1}^{j^*_{\min}} \frac{1}{\tau_i}\right)^{-1} \left(S + j^*_{\min}\right) = \min_{j \in [n]} g(j).
    \end{align*}
    The proof of the fourth inequality is the same, but with non-strict inequalities.
\end{proof}

